INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 200, 100101, 100101, 100101, 0, 1, 2.295, 450, 7, 1, "2015/04/01 15:00:00", 1, 0, "ひより", 100101, 0, "2030/12/31 15:00:00", 1, 0, 0, 0, "【物理】前衛で、敵前線を押し返す笑顔の元気娘。\n前衛に対して大ダメージを与えるユニオンバーストと、\n自身の攻撃力を強化するスキルを持つ攻撃役。", "ヒヨリ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 800, 100201, 100201, 100201, 0, 7, 2.27, 450, 7, 2, "2015/04/01 15:00:00", 7, 0, "ゆい", 100201, 0, "2030/12/31 15:00:00", 1, 0, 0, 0, "【魔法】最後衛から、味方の回復と補助を行う魔法士。\n打たれ弱いが高い魔法攻撃力を持ち、ランクを上げると\n攻撃も補助もバランスよくこなせるようになる。", "ユイ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 250, 100301, 100301, 100301, 0, 4, 1.965, 450, 7, 1, "2015/04/01 15:00:00", 4, 0, "れい", 100301, 0, "2030/12/31 15:00:00", 1, 0, 0, 0, "【物理】前衛で、一点突破で敵を討つ、孤高の剣士。\nユニオンバースト、スキル共に眼前の敵を倒す事に優れ、\n高火力の攻撃スキルを駆使して前線を押し上げる。", "レイ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 205, 100401, 100401, 100401, 0, 1, 2.17, 450, 13, 1, "2015/04/01 15:00:00", 1, 0, "みそぎ", 100401, 0, "2030/12/31 15:00:00", 1, 0, 0, 0, "【物理】最前衛で、敵の物理攻撃を邪魔するいたずら娘。\n目の前の敵を暗闇状態にし、命中率を大幅に下げるほか、\n敵一体の物理攻撃力を下げるスキルを持つ。", "ミソギ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 185, 100501, 100501, 100501, 0, 2, 2.125, 450, 2, 1, "2018/09/18 15:00:00", 2, 0, "まつり", 100501, 0, "2030/12/31 15:00:00", 2, 0, 0, 0, "【物理】前衛の、機敏な動きで敵をかき回す騎士見習い。\nユニオンバーストで相手の陣地の真ん中に飛び込み、\n自分の周囲を攻撃するスキルで相手を攻め立てる。", "マツリ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 570, 100601, 100601, 100601, 0, 6, 2.19, 450, 14, 2, "2015/04/01 15:00:00", 6, 0, "あかり", 100601, 0, "2030/12/31 15:00:00", 2, 0, 0, 0, "【魔法】中衛で、魔法パーティの強化を担う、双子の妹。\n敵の魔法防御力を大幅に下げるスキルや、魔法攻撃力を\n上昇させ、回復効果を付与するユニオンバーストを使う。", "アカリ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 125, 100701, 100701, 100701, 0, 3, 1.7, 450, 14, 1, "2015/04/01 15:00:00", 3, 0, "みやこ", 100701, 0, "2030/12/31 15:00:00", 2, 0, 0, 0, "【物理】最前衛で、ひたすら敵の攻撃を避ける幽霊少女。\nスキルで幽霊に変身することで敵の攻撃を躱し、\nユニオンバーストでは敵をプリンにして食べてしまう。", "ミヤコ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 805, 100801, 100801, 100801, 0, 21, 2.07, 450, 12, 2, "2015/04/01 15:00:00", 7, 0, "ゆき", 100801, 0, "2030/12/31 15:00:00", 2, 0, 0, 0, "【魔法】後衛で物理パーティを補助する、歩く芸術作品。\n味方のユニオンバースト発動を早めるスキルのほか、\n暗闇状態にするスキルで敵の物理攻撃を封じる。", "ユキ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 440, 100901, 100901, 100901, 0, 5, 2.25, 450, 11, 2, "2015/04/01 15:00:00", 5, 0, "あんな", 100901, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】中衛から圧倒的な魔力で攻撃する、疾風の冥姫。\nユニオンバーストで敵全体に大ダメージを与えるが、\n高すぎる魔力の為、自分自身にも相応のリスクが生じる。", "アンナ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 795, 101001, 101001, 101001, 0, 7, 2.27, 450, 4, 2, "2015/04/01 15:00:00", 7, 0, "まほ", 101001, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】後衛で味方のサポートを担当するメルヘン少女。\n味方全体を強化してＴＰを回復するユニオンバーストや、\nＨＰ回復、敵を暗闇にするスキルで戦況を好転させる。", "マホ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 700, 101101, 101101, 101101, 0, 8, 1.97, 450, 6, 1, "2015/04/01 15:00:00", 8, 0, "りの", 101101, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】後衛から、矢の雨を降らせる妹系アーチャー。\nクリティカル率を高める重ね掛け可能なスキルを持ち、\nダメージ回数の多いユニオンバーストをより強力にする。", "リノ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 755, 101201, 101201, 101201, 0, 7, 2.07, 450, 9, 2, "2015/04/01 15:00:00", 7, 0, "はつね", 101201, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】後衛の、対物理パーティが得意な超能力ガール。\nスキルが物理攻撃の敵に対して真価を発揮するため、\n物理攻撃型の敵パーティを一網打尽にする。", "ハツネ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 740, 101301, 101301, 101301, 0, 7, 2.07, 450, 9, 2, "2018/11/19 15:00:00", 7, 0, "ななか", 101301, 0, "2030/12/31 15:00:00", 2, 0, 0, 0, "【魔法】後衛から多彩な魔法を放つ、オタク魔法少女。\n体力が一番多い相手を狙うユニオンバーストやスキルは、\n敵のＨＰ状況により攻撃対象が変わる高威力の魔法攻撃。", "ナナカ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 730, 101401, 101401, 101401, 0, 21, 2.27, 450, 9, 2, "2019/02/28 12:00:00", 7, 0, "かすみ", 101401, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】後衛で、相手の行動妨害に特化した名探偵。\n束縛や混乱を付与するスキルで相手の行動を妨害し、\n魔法防御力ダウンのフィールドを展開して王手をかける。", "カスミ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 735, 101501, 101501, 101501, 0, 9, 2.27, 450, 9, 2, "2015/04/01 15:00:00", 7, 0, "みさと", 101501, 0, "2030/12/31 15:00:00", 2, 0, 0, 0, "【魔法】後衛で魔法キャラを支援する、みんなの先生。\nユニオンバーストのＨＰ回復＆魔防アップ、先頭キャラの\n継続ＨＰ回復スキルは、味方の耐久力を大幅に高める。", "ミサト");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 705, 101601, 101601, 101601, 0, 8, 1.97, 450, 15, 1, "2015/04/01 15:00:00", 8, 0, "すずな", 101601, 0, "2030/12/31 15:00:00", 2, 0, 0, 0, "【物理】後衛からクリティカル攻撃するカリスマモデル。\n必ずクリティカルするユニオンバーストのダメージは\nスキルによる攻撃力アップでさらに破壊力を増す。", "スズナ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 145, 101701, 101701, 101701, 0, 1, 2.17, 450, 4, 1, "2015/04/01 15:00:00", 1, 0, "かおり", 101701, 0, "2030/12/31 15:00:00", 2, 0, 0, 0, "【物理】最前衛で、累積スキルでダメージを稼ぐ南国娘。\nスキル「精神統一」を発動すると、カオリが攻撃する度に\n敵に効果が累積し、次のダメージがどんどん増えていく。", "カオリ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 715, 101801, 101801, 101801, 0, 5, 2.6, 450, 15, 2, "2015/04/01 15:00:00", 5, 0, "いお", 101801, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】後衛で、敵全体を誘惑するセクシー先生。\n敵のＴＰを奪うスキルでユニオンバースト発動を遅らせ、\n誘惑のユニオンバーストを放ち、戦場を大混乱に陥れる。", "イオ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 360, 102001, 102001, 102001, 0, 5, 2.125, 450, 13, 1, "2015/04/01 15:00:00", 5, 0, "みみ", 102001, 0, "2030/12/31 15:00:00", 2, 0, 0, 0, "【物理】中衛で、敵前衛を崩す、うさぎっこ。\nユニオンバーストは、最も近い敵に大ダメージを与えた後\n隣の敵にも攻撃するので、前衛を早期に攻め落とせる。", "ミミ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 197, 102101, 102101, 102101, 0, 3, 1.675, 450, 3, 1, "2015/04/01 15:00:00", 3, 0, "くるみ", 102101, 0, "2030/12/31 15:00:00", 1, 0, 0, 0, "【物理】前衛で、味方の守りに特化した、極度の照れ屋。\nスキルで自分の周囲の物理、魔法防御力を上げつつ、\n近くの敵をスタンさせて足止めする。", "クルミ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 575, 102201, 102201, 102201, 0, 6, 2.19, 450, 14, 2, "2015/04/01 15:00:00", 6, 0, "より", 102201, 0, "2030/12/31 15:00:00", 1, 0, 0, 0, "【魔法】中衛から、強力な魔法で攻め立てる、双子の姉。\n自身のＨＰと引き換えに魔法攻撃力を増幅し、\nユニオンバーストやスキルの威力を高めて攻撃する。", "ヨリ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 210, 102301, 102301, 102301, 0, 3, 1.425, 450, 3, 1, "2015/04/01 15:00:00", 3, 0, "あやね", 102301, 0, "2030/12/31 15:00:00", 2, 0, 0, 0, "【物理】前衛で、戦場をかき乱す、くまっ子。\nユニオンバーストで、相手を思い切り吹き飛ばすと同時に\nスタンと大ダメージを与えることで敵陣形を大きく乱す。", "アヤネ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 720, 102501, 102501, 102501, 0, 7, 2.27, 450, 3, 2, "2015/04/01 15:00:00", 7, 0, "すずめ", 102501, 0, "2030/12/31 15:00:00", 1, 0, 0, 0, "【魔法】後衛で、回復と攻撃をこなすドジっ娘メイド。\n周りの味方のＨＰを回復しつつ物理攻撃力を高める\nスキルは、中衛・後衛の攻撃役と抜群の相性。", "スズメ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 550, 102601, 102601, 102601, 0, 6, 2.34, 450, 3, 1, "2015/04/01 15:00:00", 6, 0, "りん", 102601, 0, "2030/12/31 15:00:00", 2, 0, 0, 0, "【物理】中衛で物理パーティを強化するものぐさ少女。\n味方の物理攻撃力をアップしつつ、味方の魔法防御を\n高めることで攻守ともにパーティをサポートする。", "リン");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 230, 102701, 102701, 102701, 0, 3, 1.425, 450, 11, 1, "2015/04/01 15:00:00", 3, 0, "えりこ", 102701, 0, "2030/12/31 15:00:00", 2, 0, 0, 0, "【物理】前衛で、毒スキルで敵を粉砕する、通称壊し屋。\n最高クラスの攻撃力を持ち、ユニオンバーストで敵に\nとどめの一撃を放つ毎に、その攻撃力はさらに上昇する。", "エリコ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 430, 102801, 102801, 102801, 0, 4, 2.09, 450, 3, 1, "2015/04/01 15:00:00", 4, 0, "されん", 102801, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】中衛で一発逆転を狙う、みんなのサレンママ。\nＨＰが下がるほどダメージが上昇するユニオンバーストと\n味方のＴＰを回復するスキルで、一気に形勢を逆転する。", "サレン");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 160, 102901, 102901, 102901, 0, 4, 1.965, 450, 10, 1, "2015/04/01 15:00:00", 4, 0, "のぞみ", 102901, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】前衛で、皆の壁になって戦うアイドルのぞみん。\n彼女がステージに立てば、味方の物理攻撃力が\n大きくアップし、さらに敵の注意を一手に惹き付ける。", "ノゾミ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 415, 103001, 103001, 103001, 0, 5, 2.25, 450, 12, 1, "2015/04/01 15:00:00", 5, 0, "にのん", 103001, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】中衛で、強力な範囲攻撃を操る、忍術の使い手。\n範囲攻撃のスキルで敵を倒す事で、自分のＴＰを回復し、\n強力なユニオンバーストの発動頻度を上げる。", "ニノン");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 365, 103101, 103101, 103101, 0, 5, 2.25, 450, 14, 1, "2015/04/01 15:00:00", 5, 0, "しのぶ", 103101, 0, "2030/12/31 15:00:00", 2, 0, 0, 0, "【物理】中衛で、父親のドクロを召喚して戦う霊能少女。\n召喚した父親は、自分とは別に攻撃を行ってくれるほか、\nダメージを代わりに受けてくれることもある。", "シノブ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 180, 103201, 103201, 103201, 0, 5, 2.125, 450, 8, 1, "2015/04/01 15:00:00", 5, 0, "あきの", 103201, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】前衛で大暴れして攻める、令嬢剣士。\n自分の周りに、味方を回復するフィールドを作り出し、\n自ら前線を支え導く姿も、名家を背負う者のあるべき姿。", "アキノ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 395, 103301, 103301, 103301, 0, 6, 2.34, 450, 5, 1, "2015/04/01 15:00:00", 6, 0, "まひる", 103301, 0, "2030/12/31 15:00:00", 2, 0, 0, 0, "【物理】中衛で、相手の動きを乱す牧場主。\n敵前衛をノックバックさせることで、隊列を崩し、\n他のキャラが使う範囲攻撃の対象に敵を押し込む。", "マヒル");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 405, 103401, 103401, 103401, 0, 5, 2.4, 450, 8, 1, "2015/04/01 15:00:00", 5, 0, "ゆかり", 103401, 0, "2030/12/31 15:00:00", 1, 0, 0, 0, "【物理】中衛から、バリアや回復で味方を守る元聖騎士。\n傷ついた味方のＨＰやＴＰを回復するスキルを操り、\n打ち合いで消耗した所を、ピンポイントでサポートする。", "ユカリ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 810, 103601, 103601, 103601, 0, 7, 2.07, 450, 0, 2, "2015/04/01 15:00:00", 7, 0, "きょうか", 103601, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】後衛から強力な魔法で攻撃するちびっこ優等生。\nスキルで魔法攻撃力を瞬間的に高めた後に放つ\nユニオンバーストは威力抜群。", "キョウカ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 220, 103701, 103701, 103701, 0, 4, 1.965, 450, 2, 1, "2015/04/01 15:00:00", 4, 0, "とも", 103701, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】前衛で、素早い斬撃を仕掛け敵を屠る剣術少女。\nユニオンバーストで自分の攻撃力と行動速度を上昇させ、\nほか攻撃スキルの殲滅能力を極限まで高め敵を圧倒する。", "トモ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 710, 103801, 103801, 103801, 0, 8, 1.97, 450, 5, 1, "2015/04/01 15:00:00", 8, 0, "しおり", 103801, 0, "2030/12/31 15:00:00", 2, 0, 0, 0, "【物理】最後衛から高火力スキルを連発するスナイパー。\nダメージを与えつつ、ＴＰを回復するスキルを持ち、\n強力な一撃のユニオンバーストを、素早く発動する。", "シオリ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 785, 104001, 104001, 104001, 0, 8, 1.97, 450, 9, 1, "2015/04/01 15:00:00", 8, 0, "あおい", 104001, 0, "2030/12/31 15:00:00", 1, 0, 0, 0, "【物理】最後衛から状態異常の矢を放つ、ぼっちの射手。\nダメージと共に付与する毒や麻痺の追加効果により、\n防御力の高い敵であっても、確実にＨＰを削りとる。", "アオイ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 790, 104201, 104201, 104201, 0, 7, 2.27, 450, 10, 2, "2015/04/01 15:00:00", 7, 0, "ちか", 104201, 0, "2030/12/31 15:00:00", 2, 0, 0, 0, "【魔法】後衛から、前衛の戦いをサポートする唱喚士。\n自身のユニオンバーストで味方のＨＰを回復し、唱喚した\n精霊は敵への攻撃と唱喚者の魔法攻撃力強化を行う。", "チカ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 165, 104301, 104301, 104301, 0, 5, 2.125, 450, 4, 1, "2015/04/01 15:00:00", 5, 0, "まこと", 104301, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】前衛で、敵の防御力を削り取る、正義の獣人。\n敵の盾役の防御力を下げ、着実にダメージを与えることで\n早期に敵の守りを突破する。", "マコト");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 425, 104401, 104401, 104401, 0, 3, 1.425, 450, 12, 2, "2015/04/01 15:00:00", 3, 0, "いりや", 104401, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】中衛で命を削り攻撃する「夜を統べる者」。\n自身のＨＰと引き換えに放つスキルは高い殲滅力を誇り\n範囲攻撃における威力では他の追随を許さない。", "イリヤ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 130, 104501, 104501, 104501, 0, 2, 2.375, 450, 12, 1, "2015/04/01 15:00:00", 2, 0, "くうか", 104501, 0, "2030/12/31 15:00:00", 2, 0, 0, 0, "【物理】前衛で囮となり、攻撃を引き付ける暴走ドＭ娘。\nユニオンバーストにより、自身に魔法バリアを張り、\n敵の魔法攻撃を吸収してＨＰを回復する。", "クウカ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 215, 104601, 104601, 104601, 0, 2, 2.25, 450, 8, 1, "2015/04/01 15:00:00", 2, 0, "たまき", 104601, 0, "2030/12/31 15:00:00", 2, 0, 0, 0, "【物理】前衛の、対魔法パーティが得意な気まぐれ猫娘。\n攻撃スキルは、「魔法攻撃力が一番高い敵」を狙い撃ち、\nダメージ、魔法攻撃力ダウン、ＴＰ吸収と畳み掛ける。", "タマキ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 135, 104701, 104701, 104701, 0, 5, 2.125, 450, 2, 1, "2015/04/01 15:00:00", 5, 0, "じゅん", 104701, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】最前衛で、完全防御スキルを操る騎士団長。\nユニオンバーストであらゆるダメージを吸収するバリアを\n展開できる。特に長期戦で圧倒的な防御性能を誇る。", "ジュン");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 420, 104801, 104801, 104801, 0, 6, 2.19, 450, 8, 1, "2015/04/01 15:00:00", 6, 0, "みふゆ", 104801, 0, "2030/12/31 15:00:00", 2, 0, 0, 0, "【物理】中衛の、スタンと回復のスキルを持つ傭兵戦士。\n高い防御力と自己回復能力を併せ持つ事で、\n中衛の守りを堅固にし、パーティを底支えする。", "ミフユ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 285, 104901, 104901, 104901, 0, 5, 2.375, 450, 6, 1, "2015/04/01 15:00:00", 5, 0, "しずる", 104901, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】前衛で、物理攻撃から味方を守る、お姉ちゃん。\nスキルで物理無効バリアを展開し、味方全員を守るほか、\n自身はさらに物理吸収バリアを纏い、敵前衛を討つ。", "シズル");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 760, 105001, 105001, 105001, 0, 7, 2.07, 450, 15, 2, "2015/04/01 15:00:00", 7, 0, "みさき", 105001, 0, "2030/12/31 15:00:00", 1, 0, 0, 0, "【魔法】後衛から、範囲攻撃を行う、レディ・ウィッチ。\n複数回の範囲攻撃を放つスキルや、目の前の敵全てを\n攻撃するユニオンバーストを持ち、範囲殲滅に特化する。", "ミサキ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 565, 105101, 105101, 105101, 0, 5, 2.25, 450, 11, 1, "2015/04/01 15:00:00", 5, 0, "みつき", 105101, 0, "2030/12/31 15:00:00", 2, 0, 0, 0, "【物理】中衛で、敵弱体化フィールドを操る隻眼の悪魔。\nフィールドの持続時間は短いが、範囲内の敵の\n物理防御力を大幅に減らす効果を持つ。", "ミツキ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 105, 105201, 105201, 105201, 0, 4, 2.215, 450, 5, 1, "2015/04/01 15:00:00", 4, 0, "りま", 105201, 0, "2030/12/31 15:00:00", 1, 0, 0, 0, "【物理】最前衛で味方を守る、恋する乙女。\nバトル開始後、しばらくしてから最前線まで\n突進してきて、敵の目の前に立ちはだかる。", "リマ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 410, 105301, 105301, 105301, 0, 4, 2.24, 450, 12, 1, "2015/04/01 15:00:00", 4, 0, "もにか", 105301, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】中衛で、味方の攻撃を鼓舞する、軍人娘。\n味方全体の物理、魔法攻撃力の大幅アップに加えて、\n攻撃速度もあげることで、戦闘の早期終結を実現する。", "モニカ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 195, 105401, 105401, 105401, 0, 1, 2.42, 450, 10, 1, "2015/04/01 15:00:00", 1, 0, "つむぎ", 105401, 0, "2030/12/31 15:00:00", 2, 0, 0, 0, "【物理】前衛で、敵の妨害に特化したテーラーガール。\n敵を強制的に移動させる事で陣形を崩し、さらに\n移動速度・行動速度を低下させ相手の反撃を遅らせる。", "ツムギ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 510, 105501, 105501, 105501, 0, 48, 2.34, 450, 12, 1, "2019/03/19 15:00:00", 48, 0, "あゆみ", 105501, 0, "2030/12/31 15:00:00", 1, 0, 0, 0, "【物理】中衛で、どたばたと敵をかく乱する、純情少女。\n敵をスタンさせるスキルのほか、ユニオンバーストでは\n暗闇と混乱を付与することで敵を邪魔することができる。", "アユミ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 158, 105601, 105601, 105601, 0, 4, 1.965, 450, 2, 1, "2018/11/03 19:00:00", 4, 0, "るか", 105601, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】前衛で味方のため剣を振るう、いなせな姉御。\n相手へのカウンターも行う挑発や、敵の防御力を下げる\nユニオンバーストを持ち、攻防両面で実力を発揮する。", "ルカ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 245, 105701, 105701, 170101, 0, 4, 1.965, 450, 4, 1, "2015/04/01 15:00:00", 4, 0, "じーた", 105701, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】前衛で、先手必勝の大技を繰り出す騎空士。\nスキルによるＴＰ回復は、ユニオンバーストの発動を早め\nバトルの序盤から敵前衛に大ダメージを与える。", "ジータ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 155, 105801, 105801, 105801, 0, 5, 2.25, 450, 1, 1, "2015/04/01 15:00:00", 5, 0, "ぺこりーぬ", 105801, 0, "2030/12/31 15:00:00", 1, 0, 0, 0, "【物理】前衛にて、全力で仲間を護る、腹ペコ剣士。\n高いＨＰに加えて、自分自身でもＨＰ回復できるため\nギリギリまで味方の壁役を引き受ける。", "ペコリーヌ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 500, 105901, 105901, 105901, 0, 6, 2.34, 450, 1, 1, "2015/04/01 15:00:00", 6, 0, "こっころ", 105901, 0, "2030/12/31 15:00:00", 1, 0, 0, 0, "【物理】中衛で、補助と攻撃で皆を支える、導きの巫女。\nユニオンバーストは、味方全体の攻撃力アップに加えて\n自らも回復するため、継続的なサポートが可能となる。", "コッコロ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 750, 106001, 106001, 106001, 0, 7, 2.07, 450, 1, 2, "2015/04/01 15:00:00", 7, 0, "きゃる", 106001, 0, "2030/12/31 15:00:00", 1, 0, 0, 0, "【魔法】後衛から、強力な全体攻撃を放つ、強気な猫娘。\nスキルで敵の物理、魔法両方の防御力を下げるため\n編成を選ばずにバトルを有利に進められる。", "キャル");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 162, 106101, 106101, 106101, 0, 2, 1.8, 450, 7, 1, "2026/10/23 12:00:00", 2, 0, "むいみ", 106101, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【物理】前衛で、伝説の剣「天楼覇断剣」を振るう少女。\n小技を駆使する通常の戦闘スタイルから一転、ユニオン\nバースト後は「天楼覇断剣」を携え、敵を薙ぎ払う。", "ムイミ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 625, 106301, 106301, 106301, 0, 8, 1.97, 450, 1, 1, "2015/04/01 15:00:00", 8, 0, "ありさ", 106301, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】後衛の、長期戦に優れた、森の守護者見習い。\nＴＰ回復によるユニオンバーストの速攻が可能。さらに\n使用後はスキル効果が上昇するため高い殲滅力を誇る。", "アリサ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 368, 106401, 106401, 106401, 0, 4, 1.84, 450, 1, 1, "2021/02/15 23:00:00", 4, 0, "しぇふぃ", 106401, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】中衛で氷雪を操り敵を凍滅する、氷竜の少女。\nユニオンバーストで獲得する【氷竜の印】を消費して、\nスキルの効果を増幅し、清廉な剣技で敵を切り伏せる。", "シェフィ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 168, 106501, 106501, 106501, 0, 1, 2.17, 450, 17, 1, "2019/11/15 15:00:00", 1, 0, "かや", 106501, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】前衛で、敵を殴り倒す喧嘩屋ドラゴン族。\nスキルで自身の物理攻撃力を高め、全身全霊を懸け放つ\n初弾のユニオンバーストは、超大な破壊力を誇る。", "カヤ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 197, 106601, 106601, 106601, 0, 3, 1.55, 450, 17, 1, "2020/06/17 15:00:00", 3, 0, "いのり", 106601, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】前衛で範囲攻撃が得意な口達者のドラゴン娘。\nユニオンバーストで範囲内の敵をまとめて吹き飛ばし、\n陣形を乱したところで、敵を一気に焼き尽くす。", "イノリ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 727, 106701, 106701, 106701, 0, 21, 2.27, 450, 17, 2, "2026/10/23 12:00:00", 7, 0, "ほまれ", 106701, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【魔法】後衛から無窮の魔力で全てを支配する龍の首領。\n障壁となる敵を龍眼で捉え、多彩な補助系スキルで敵の\n魔法攻撃からの耐性を弱め、雷霆の一撃で灰燼に帰す。", "ホマレ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 560, 106801, 106801, 106801, 0, 4, 1.55, 450, 6, 1, "2026/10/23 12:00:00", 4, 0, "らびりすた", 106801, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【物理】中衛で、万有を自在に創造する『迷宮女王』。\n七冠としての権能を解放するユニオンバーストで自身を\n極大に強化し比類ない攻撃能力で仇なす者を剿滅する。", "ラビリスタ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 660, 106901, 106901, 106901, 0, 0, 2, 450, 1, 1, "2022/11/15 15:00:00", 45, 0, "かいざーいんさいと", 106901, 0, "2030/12/31 15:00:00", 3, 1, 0, 0, "【物理】後衛で、天の星を瞳に宿し、覇道を進む皇。\n権能を解放し敵全体のバリアと全ステータスアップ効果を\n解除し、耐久力ダウンと複数の広範囲攻撃で敵を滅する。", "カイザーインサイト");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 660, 107001, 107001, 107001, 0, 0, 2, 450, 1, 2, "2026/10/23 12:00:00", 0, 0, "ねねか", 107001, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【魔法】後衛で、分身生成し敵を圧倒する『変貌大妃』。\n分身はネネカ自身と同じスキルをくり出し敵を攻撃する。\nその攻撃密度と制圧力の高さは他の追随を許さない。", "ネネカ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 290, 107101, 107101, 107101, 0, 10, 2, 450, 2, 1, "2026/10/23 12:00:00", 4, 0, "くりすてぃーな", 107101, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【物理】前衛で、絶対的な制圧力を誇る『誓約女君』。\n攻防一体かつ超大な破壊力を誇るユニオンバーストと、\nその発動を加速するＴＰ上昇アップスキルを併せ持つ。", "クリスティーナ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 235, 107501, 107501, 107501, 0, 5, 2.125, 450, 1, 1, "2026/06/22 12:00:00", 5, 0, "ぺこりーぬ", 107501, 0, "2026/06/30 11:59:59", 3, 1, 0, 0, "【物理】前衛から強烈な範囲攻撃を放つ、渚のお姫様。\nかき氷を食べて物理攻撃力を一気に上昇させ、\nユニオンバーストを放つことで前方の敵を殲滅する。", "ペコリーヌ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 535, 107601, 107601, 107601, 0, 6, 2.34, 450, 1, 1, "2020/06/19 15:00:00", 6, 0, "こっころ", 107601, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【物理】中衛で、物理キャラの補助を行う癒しの巫女。\nＨＰが一番少ない味方単体への特大回復スキルを持ち、\n瀕死の味方ですら瞬時に治癒する。", "コッコロ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 775, 107701, 107701, 107701, 0, 7, 2.07, 450, 3, 2, "2026/06/22 12:00:00", 7, 0, "すずめ", 107701, 0, "2026/06/30 11:59:59", 3, 1, 0, 0, "【魔法】後衛の防衛能力に秀でた、夏のドジっ娘メイド。\n味方全体に防御力アップと継続ＨＰ回復をかけ、\nさらに壁になるゴーレムを呼んで、戦線を支える。", "スズメ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 780, 107801, 107801, 107801, 0, 7, 1.92, 450, 1, 2, "2026/06/22 12:00:00", 7, 0, "きゃる", 107801, 0, "2026/06/30 11:59:59", 3, 1, 0, 0, "【魔法】後衛から強力な単体攻撃を放つ真夏の猫娘。\nスキルで敵の魔法防御力を下げた上で、\n敵単体への魔法攻撃を繰り出し、大ダメージを与える。", "キャル（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 225, 107901, 107901, 107901, 0, 2, 2, 450, 8, 1, "2026/06/22 12:00:00", 2, 0, "たまき", 107901, 0, "2026/06/30 11:59:59", 3, 1, 0, 0, "【物理】前衛で連続攻撃を放つ、海辺の気まぐれ猫娘。\nランダムな相手への単体攻撃を計４度行う\nユニオンバーストは、対象がランダムだが威力は抜群。", "タマキ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 495, 108001, 108001, 108001, 0, 6, 2.19, 450, 8, 1, "2020/07/20 15:00:00", 6, 0, "みふゆ", 108001, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【物理】中衛で、攻撃と補助の両方をこなす海の傭兵。\nユニオンバーストの効果で味方全体の物理攻撃力を高め、\n物理攻撃パーティの能力アップに一役買う。", "ミフユ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 440, 108101, 108101, 108101, 0, 3, 1.55, 450, 0, 1, "2025/11/14 15:00:00", 3, 0, "しのぶ", 108101, 0, "2025/11/30 11:59:59", 3, 1, 0, 0, "【物理】中衛で、迷える魂を導き救う幻夜の霊能少女。\nユニオンバーストは最も物理防御力の低い敵を狙うととも\nに、召喚された仮初の存在を一閃のもとに刈り取る。", "シノブ（ハロウィン）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 590, 108201, 108201, 108201, 0, 1, 2.42, 450, 0, 1, "2020/09/23 15:00:00", 1, 0, "みやこ", 108201, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【物理】中衛から、敵陣の後方を狙い撃つ幽霊狼少女。\n前方の相手を無視して妨害スキルやユニオンバーストを\n敵後方に放ち、特に防御力が低いキャラの脅威になる。", "ミヤコ（ハロウィン）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 815, 108301, 108301, 108301, 0, 7, 2.07, 450, 15, 2, "2026/10/15 12:00:00", 7, 0, "みさき", 108301, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【魔法】後衛で、妨害スキルを操るオシャレ魔法少女。\n相手を誘惑状態にするスキルや、複数の状態異常を\n同時に付与するユニオンバーストで相手をかく乱する。", "ミサキ（ハロウィン）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 770, 108401, 108401, 108401, 0, 7, 2.27, 450, 10, 2, "2025/12/21 12:00:00", 7, 0, "ちか", 108401, 0, "2025/12/31 11:59:59", 3, 1, 0, 0, "【魔法】後衛で、精霊を唱喚して戦う雪華の歌姫。\nユニオンバーストで呼び出す精霊たちはＨＰやＴＰを\n回復する能力を持ち、不利な戦況をも一変させる。", "チカ（クリスマス）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 295, 108501, 108501, 108501, 0, 3, 1.55, 450, 15, 1, "2020/11/24 15:00:00", 3, 0, "くるみ", 108501, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【物理】前衛から、ベルの音色で味方を守る小さな女優。\n攻撃を受けるまで周囲にいる味方の防御力を大きく高める\nスキルを持つ。活用できれば無類の耐久力を誇る。", "クルミ（クリスマス）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 190, 108601, 108601, 108601, 0, 3, 1.425, 450, 10, 1, "2025/12/21 12:00:00", 3, 0, "あやね", 108601, 0, "2025/12/31 11:59:59", 3, 1, 0, 0, "【物理】前衛で、敵をなぎ倒していく聖夜のくまっ子。\nユニオンバーストはＨＰを消費するが威力は絶大。\nスキルで物理攻撃力を上げ、さらにダメージアップ。", "アヤネ（クリスマス）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 170, 108701, 108701, 108701, 0, 1, 2.17, 450, 7, 1, "2026/01/15 12:00:00", 1, 0, "ひより", 108701, 0, "2026/01/31 11:59:59", 3, 1, 0, 0, "【物理】前衛で、物理火力を担う、振り袖姿の元気娘。\n物理攻撃キャラの攻撃力を上昇させるスキルを使う。\nさらに高い威力の単体ユニオンバーストの攻撃力は随一。", "ヒヨリ（ニューイヤー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 745, 108801, 108801, 108801, 0, 21, 2.27, 450, 7, 2, "2026/01/15 12:00:00", 7, 0, "ゆい", 108801, 0, "2026/01/31 11:59:59", 3, 1, 0, 0, "【魔法】後衛の、補助魔法に特化した、晴れ姿の癒し手。\n自身の攻撃力と引き換えに強力なバリアと継続回復状態を\n味方全体に付与する。絶大な防御能力は他を圧倒する。", "ユイ（ニューイヤー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 153, 108901, 108901, 108901, 0, 22, 2.215, 450, 7, 1, "2020/12/22 15:00:00", 4, 0, "れい", 108901, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【物理】前衛で、魔法攻撃から味方を守る、華麗な剣士。\nスキルで範囲内の味方に魔法無効バリアを展開し、\nさらにユニオンバーストで敵をスタンさせ攻撃を断つ。", "レイ（ニューイヤー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 187, 109001, 109001, 109001, 0, 3, 1.9, 450, 11, 1, "2021/01/25 15:00:00", 3, 0, "えりこ", 109001, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【物理】前衛で、ピンチをチャンスに変える愛の壊し屋。\nスキルはＨＰを消費し、自身の攻撃力を高める。また、\nユニオンバーストはＨＰが低いほど超絶威力を発揮する。", "エリコ（バレンタイン）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 385, 109101, 109101, 109101, 0, 5, 2.125, 450, 7, 1, "2026/01/31 12:00:00", 5, 0, "しずる", 109101, 0, "2026/02/09 11:59:59", 3, 1, 0, 0, "【物理】中衛で皆を助けるパティシエールのお姉ちゃん。\n複数のパラメータが同時に上昇するフィールドを展開し、\nさらに効果時間中はスキル効果が大幅に強化される。", "シズル（バレンタイン）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 630, 109201, 109201, 109201, 0, 23, 2.27, 450, 6, 2, "2019/03/31 12:00:00", 7, 0, "あん", 109201, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】後衛で、英霊の召喚術を武器に戦うお姫様。\n味方に英霊の加護を付与するスキルによるサポーターと、\n高威力の魔法によるアタッカーの二つの役割を併せ持つ。", "アン");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 640, 109301, 109301, 109301, 0, 23, 2.27, 450, 9, 2, "2021/03/23 15:00:00", 7, 0, "るぅ", 109301, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【魔法】後衛で、オメメちゃんと戦う、ノーテンキ少女。\nスキルで呼び出すオメメちゃんは敵の攻撃を防ぐほか、\nその数が多いほどユニオンバーストの威力を増加させる。", "ルゥ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 525, 109401, 109401, 109401, 0, 1, 2.27, 450, 9, 2, "2019/04/19 15:00:00", 1, 0, "ぐれあ", 109401, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】中衛で、炎を操り敵を薙ぎ払う、竜人の少女。\n高い魔法攻撃力を生かした範囲攻撃を得意とする。\nまた、飛行能力を駆使して放つ突進攻撃も強力。", "グレア");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 140, 109501, 109501, 109501, 0, 2, 2.066, 450, 12, 2, "2019/04/30 12:00:00", 7, 0, "くうか", 109501, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】最前衛で、味方を鼓舞する着物姿のドＭ娘。\n味方の魔法攻撃力を高め、敵の魔法防御力を下げる事で、\n魔法パーティのサポート兼防御役として活躍する。", "クウカ（オーエド）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 175, 109601, 109601, 109601, 0, 2, 2, 450, 12, 1, "2019/05/17 15:00:00", 2, 0, "にのん", 109601, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】最前衛で、忍法を駆使して敵と戦うクノイチ。\nユニオンバーストはクリティカル時のダメージを１．５倍\nにする特性を持ち、うまくかみ合った時の威力は抜群。", "ニノン（オーエド）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 540, 109701, 109701, 109701, 0, 24, 2.25, 450, 9, 1, "2025/10/10 12:00:00", 13, 1, "れむ", 109701, 0, "2025/10/24 11:59:59", 3, 1, 0, 0, "【物理】中衛で、鬼の力で敵を粉砕する、双子の妹。\n回復スキルの他にも、温度を操るスキルを得意とし、\n敵を凍結させた上でユニオンバーストで薙ぎ払う。", "レム");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 545, 109801, 109801, 109801, 0, 24, 2.5, 450, 9, 2, "2015/04/01 15:00:00", 7, 1, "らむ", 109801, 0, "2030/12/31 15:00:00", 1, 1, 1, 0, "【魔法】中衛で、特殊能力で味方を補助する、双子の姉。\n相手の物理攻撃を見切って回避させる「千里眼」や、\n敵全体を束縛するユニオンバーストの補助は効果絶大。", "ラム");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 725, 109901, 109901, 109901, 0, 23, 2.27, 450, 9, 2, "2025/10/10 12:00:00", 7, 1, "えみりあ", 109901, 0, "2025/10/24 11:59:59", 3, 1, 0, 0, "【魔法】後衛で、攻撃と回復をこなす、ハーフエルフ。\n高い魔力で攻撃魔法を繰り出して敵を蹴散らしつつ、\nユニオンバーストは瀕死の味方すらも瞬時に癒す。", "エミリア");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 705, 110001, 110001, 110001, 0, 8, 1.82, 450, 15, 1, "2026/06/22 12:00:00", 8, 0, "すずな", 110001, 0, "2026/06/30 11:59:59", 3, 1, 0, 0, "【物理】後衛で高威力の弓技を放つ夏のカリスマモデル。\nバトル中に放つ「サマーランウェイ♪」でＴＰを全回復\nして、発動後のユニオンバーストがクリティカルになる。", "スズナ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 715, 110101, 110101, 110101, 0, 5, 2.4, 450, 15, 2, "2021/05/18 15:00:00", 5, 0, "いお", 110101, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【魔法】後衛で、敵の体力を奪い取る、夏の夜の先生。\nダメージを与えつつ味方を回復するスキルを複数持ち、\n攻守どちらの側でも高い能力を発揮する。", "イオ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 0, 110201, 0, 0, 0, 7, 0, 0, 15, 0, "2015/04/01 15:00:00", 7, 0, "みさき", 110201, 0, "2030/12/31 15:00:00", 1, 0, 0, 0, "", "ミサキ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 585, 110301, 110301, 110301, 0, 4, 2.24, 450, 3, 1, "2026/06/22 12:00:00", 4, 0, "されん", 110301, 0, "2026/06/30 11:59:59", 3, 1, 0, 0, "【物理】中衛で、味方の速攻を支える海辺のサレンママ。\nバトル開始時に味方全体のＴＰを一気に溜めることで、\n迅速にユニオンバーストを発動させることを可能にする。", "サレン（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 180, 110401, 110401, 110401, 0, 5, 2.125, 450, 4, 1, "2026/07/15 12:00:00", 5, 0, "まこと", 110401, 0, "2026/07/31 11:59:59", 3, 1, 0, 0, "【物理】前衛で攻撃対象が１つの敵に特化した海の狼娘。\n攻撃対象が１つの場合、スキルとユニオンバーストともに\n真価を発揮し他を圧倒する絶大な破壊力で敵をなぎ払う。", "マコト（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 425, 110501, 110501, 110501, 0, 1, 2.42, 450, 4, 1, "2021/06/18 15:00:00", 1, 0, "かおり", 110501, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【物理】中衛で、敵をまとめてなぎ倒す、真夏の南国娘。\n吹き飛ばし効果を持つスキルで敵をまとめ、攻撃対象が\n多い程、威力が増すユニオンバーストで敵をなぎ倒す。", "カオリ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 792, 110601, 110601, 110601, 0, 7, 2.27, 450, 4, 2, "2026/07/15 12:00:00", 7, 0, "まほ", 110601, 0, "2026/07/31 11:59:59", 3, 1, 0, 0, "【魔法】後衛で、膨大な魔力を振るう、真夏のおとぎ姫。\n高火力で対象がランダムなスキルやユニオンバーストは、\n攻撃対象が１つの敵に対して絶大なダメージを叩き出す。", "マホ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 680, 110701, 110701, 110701, 0, 8, 1.82, 450, 4, 1, "2019/09/03 21:00:00", 8, 0, "あおい", 110701, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】後衛で毒を操る、ぼっちエルフの編入生。\n敵が毒や猛毒になっていると強化される攻撃スキルと、\n敵の物理防御力を下げるスキルで味方をサポートする。", "アオイ（編入生）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 185, 110801, 110801, 110801, 0, 2, 2.125, 450, 2, 1, "2019/09/16 15:00:00", 2, 0, "くろえ", 110801, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】前衛で、手数で圧倒する、ダウナー系エルフ。\n攻撃するたびに相手に【畏縮】ステータスを追加し、\nスキルのダメージと物理防御力ダウンに磨きをかける。", "クロエ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 222, 110901, 110901, 110901, 0, 1, 2.295, 450, 2, 1, "2020/04/15 15:00:00", 1, 0, "ちえる", 110901, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】前衛でパンチを放つちぇる盛りＭＡＸな女の子。\nクリティカルを出すたびに【ちぇる】を溜め、自己を強化\nし続け、後半になるほど敵をちぇるっとじぇのさいする。", "チエル");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 807, 111001, 111001, 111001, 0, 26, 2.27, 450, 2, 2, "2020/03/31 12:00:00", 7, 0, "ゆに", 111001, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】後衛で、味方の支援に特化した象牙の塔の才媛。\n自身の攻撃力は低いが、物理攻撃力の高い味方を強化し\n更に味方全体を魔法無効バリアで護りつつ勝利へ導く。", "ユニ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 820, 111101, 111101, 111101, 0, 7, 2.07, 450, 13, 2, "2026/10/15 12:00:00", 7, 0, "きょうか", 111101, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【魔法】後衛で味方の火力を高める、黒猫仮装の優等生。\n自分の魔法攻撃力に応じて効果が強化されるものと、\n効果が累積するもの等、多彩なスキルで攻撃力を高める。", "キョウカ（ハロウィン）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 212, 111201, 111201, 111201, 0, 1, 2.17, 450, 13, 1, "2021/08/16 15:00:00", 1, 0, "みそぎ", 111201, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【物理】前衛で範囲攻撃を放つ、カボチャ衣装の悪戯娘。敵に５カウントで爆発する爆弾を仕掛けたり、カボチャの手榴弾を投げつけたりと、様々な範囲攻撃で敵を弄ぶ。", "ミソギ（ハロウィン）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 365, 111301, 111301, 111301, 0, 5, 2, 450, 13, 1, "2019/10/16 15:00:00", 5, 0, "みみ", 111301, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】中衛の、攻撃に特化した、ぐるぐるうさぎっこ。\n行動頻度は少ないが、高威力の範囲攻撃を放ち、\n味方全体の物理攻撃力を大きく高めるスキルも効果抜群。", "ミミ（ハロウィン）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 765, 111401, 111401, 111401, 0, 25, 1.87, 450, 0, 2, "2019/10/31 12:00:00", 7, 0, "るな", 111401, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】後衛で、死霊術でおともだちを作る可憐な少女。\nルナがダメージを与える度に集まってくるおともだちを、\n各スキルで消費する。消費数に応じ強大な力を発揮する。", "ルナ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 265, 111501, 111501, 111501, 0, 10, 2, 450, 13, 1, "2025/12/21 12:00:00", 4, 0, "くりすてぃーな", 111501, 0, "2025/12/31 11:59:59", 3, 1, 0, 0, "【物理】前衛で戦いを愉しむ、聖夜の『誓約女君』。\nユニオンバーストを使用すると得られるコインの有無で、\n補助と攻撃の二役を切り替え、華麗に敵を斬り倒す。", "クリスティーナ（クリスマス）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 418, 111601, 111601, 111601, 0, 4, 2.24, 450, 13, 1, "2021/10/19 15:00:00", 4, 0, "のぞみ", 111601, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【物理】中衛でパーティの守りを支えるサンタアイドル。\nスキルで物理攻撃を無効化し、後方の味方が多いほど\n物理防御力を高めるユニオンバーストで生存力を高める。", "ノゾミ（クリスマス）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 255, 111701, 111701, 111701, 0, 3, 1.3, 450, 13, 2, "2019/12/20 15:00:00", 3, 0, "いりや", 111701, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】前衛で、血を対価に敵を攻撃する聖夜の吸血鬼。\n残りＨＰが低い程ダメージが上昇するスキルと、ＨＰを\n消費するスキルを組み合わせ、絶大な破壊力を発揮する。", "イリヤ（クリスマス）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 248, 111801, 111801, 111801, 0, 22, 1.965, 450, 13, 1, "2026/03/16 10:00:00", 4, 0, "ぺこりーぬ", 111801, 0, "2026/03/31 11:59:59", 3, 1, 0, 0, "【物理】前衛で元気いっぱいに新年を祝う腹ペコお姫様。\n物理攻撃力を高めるスキルで味方を強化し、ＨＰが多い\nほどダメージが上昇するユニオンバーストで敵を討つ。", "ペコリーヌ（ニューイヤー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 159, 111901, 111901, 111901, 0, 23, 1.87, 450, 1, 1, "2026/03/16 10:00:00", 7, 0, "こっころ", 111901, 0, "2026/03/31 11:59:59", 3, 1, 0, 0, "【物理】前衛で、味方の補助に秀でた、新風の巫女。\n物理クリティカル時のダメージアップのスキルで味方の\n殲滅力を高めつつ、挑発や継続回復で耐久面を支える。", "コッコロ（ニューイヤー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 690, 112001, 112001, 112001, 0, 21, 2.07, 450, 3, 2, "2026/03/16 10:00:00", 7, 0, "きゃる", 112001, 0, "2026/03/31 11:59:59", 3, 1, 0, 0, "【魔法】後衛で、攻防双方で活躍する晴れ着姿の猫娘。\n与ダメージに応じて魔法攻撃力がアップするユニオン\nバーストで、高いベースの攻撃力がさらに強大になる。", "キャル（ニューイヤー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 722, 112101, 112101, 112101, 0, 21, 2.27, 450, 1, 2, "2021/11/16 15:00:00", 7, 0, "すずめ", 112101, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【魔法】後衛で祈りによるサポートを行うドジっ娘巫女。\nスキルの魔法無効バリアで耐久力を高め、ユニオン\nバーストでＨＰ回復と行動速度アップで戦況を整える。", "スズメ（ニューイヤー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 730, 112201, 112201, 112201, 0, 7, 2.27, 450, 9, 2, "2020/01/31 12:00:00", 7, 0, "かすみ", 112201, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】後衛の、妨害に特化した能力を持つ魔法探偵。\n相手のＴＰを大きく減少させるスキルや、遠くの敵を\n束縛するスキルを操り、相手の連携を大きく乱す。", "カスミ（マジカル）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 712, 112301, 112301, 112301, 0, 8, 1.97, 450, 5, 1, "2021/12/16 15:00:00", 8, 0, "しおり", 112301, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【物理】後衛で味方の火力の底上げを担う魔法狩人。\nユニオンバーストで味方全体の物理攻撃力を大きく高め\nスキルは範囲内の物理攻撃力を高め、輝矢の一撃を放つ。", "シオリ（マジカル）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 453, 112401, 112401, 112401, 0, 4, 2.24, 450, 18, 1, "2025/12/10 12:00:00", 4, 1, "うづき", 112401, 0, "2025/12/21 11:59:59", 3, 1, 0, 0, "【物理】中衛で、味方を鼓舞して戦う、キュートな少女。\n味方をＴＰや攻撃力をアップさせるスキルでサポートし、\n自身も強力な範囲攻撃で敵をなぎ払う。", "ウヅキ（デレマス）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 153, 112501, 112501, 112501, 0, 4, 2.215, 450, 18, 1, "2025/12/10 12:00:00", 4, 1, "りんでれます", 112501, 0, "2025/12/21 11:59:59", 3, 1, 0, 0, "【物理】前衛で、氷を創出し味方を護る、クールな少女。\n目の前の敵を束縛するスキルや挑発で行動を妨害し、\n自身にもバリアを展開し、鉄壁の防御能力を発揮する。", "リン（デレマス）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 695, 112601, 112601, 112601, 0, 7, 2.27, 450, 18, 2, "2015/04/01 15:00:00", 7, 1, "みお", 112601, 0, "2030/12/31 15:00:00", 1, 1, 1, 0, "【魔法】後衛で攻防共に活躍するパッション溢れる少女。\nダメージを受けた味方中心に回復魔法で補助をし、\nさらに魔法攻撃を仕掛けて、敵を一網打尽にする。", "ミオ（デレマス）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 422, 112701, 112701, 112701, 0, 6, 2.19, 450, 3, 1, "2020/04/30 12:00:00", 6, 0, "りん", 112701, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】中衛から、敵の守りを貫くドングリレンジャー。\n戦闘開始と共に範囲内の敵の物理防御力を大幅に下げ、\n序盤から大ダメージを与えられる戦況を作り出す。", "リン（レンジャー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 390, 112801, 112801, 112801, 0, 6, 2.19, 450, 5, 1, "2020/05/15 15:00:00", 6, 0, "まひる", 112801, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】中衛で、多勢相手が十八番のまきばの戦士。\n相手を吹き飛ばすスキルを多用し敵の陣形を押し込む。\n範囲攻撃と混乱付与スキルを駆使し一気に殲滅する。", "マヒル（レンジャー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 730, 112901, 112901, 112901, 0, 8, 1.97, 450, 6, 1, "2020/06/03 19:00:00", 8, 0, "りの", 112901, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】後衛で、希望の力で戦う、不思議の国の救世主。\nクリティカルすると効果アップのスキルや味方の数が多い\n程、威力がアップするユニオンバーストで敵を殲滅する。", "リノ（ワンダー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 508, 113001, 113001, 113001, 0, 6, 2.34, 450, 12, 1, "2020/05/31 12:00:00", 6, 0, "あゆみ", 113001, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【物理】中衛で、戦場の動向を自在に操る白兎の乙女。\n敵の行動速度をダウンさせ、味方の速度をアップさせる\nスキルと敵の時を止めるスキルで、常に味方を支える。", "アユミ（ワンダー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 192, 113101, 113101, 113101, 0, 27, 1.3, 450, 6, 1, "2026/07/15 12:00:00", 27, 0, "るか", 113101, 0, "2026/07/31 11:59:59", 3, 1, 0, 0, "【物理】前衛で、流麗な太刀捌きを魅せる若夏の姉御。\nダメージを与えた回数に応じて攻撃力が高まるスキルと、\n携えた二刀の幾刃もの斬撃で、眼前の敵を薙ぎ払う。", "ルカ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 256, 113201, 113201, 113201, 0, 28, 1.625, 450, 12, 2, "2022/04/18 15:00:00", 5, 0, "あんな", 113201, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【魔法】前衛で皆の力を借り受け力を振るう真夏の冥姫。\n味方全体の魔法攻撃力を代償に自身の魔法攻撃力を劇的に\n高め、熾烈な攻撃魔法を繰り出し大ダメージを与える。", "アンナ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 468, 113301, 113301, 113301, 0, 7, 2.07, 450, 12, 2, "2020/07/15 15:00:00", 7, 0, "ななか", 113301, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】中衛の多勢相手の戦いが得意な真夏の魔法少女。\n敵の数に応じて効果が上昇する防御力ダウンのスキルや、\n多彩な範囲攻撃を操り、真夏の戦いをサイカワに制する。", "ナナカ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 567, 113401, 113401, 113401, 0, 29, 1.92, 450, 12, 2, "2026/07/15 12:00:00", 7, 0, "はつね", 113401, 0, "2026/07/31 11:59:59", 3, 1, 0, 0, "【魔法】中衛から全体魔法攻撃を放つ超能力チアガール。\nユニオンバーストで敵全体に絶大な一撃を放ち、\nその後、超能力発動の反動で枕を抱えて夢の中へ。", "ハツネ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 697, 113501, 113501, 113501, 0, 7, 2.07, 450, 12, 2, "2022/05/18 15:00:00", 7, 0, "みさと", 113501, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【魔法】後衛で、敵の脅威から生徒を守る夏女神な先生。\n味方の魔法防御力を高め、ＨＰを継続回復するスキルや、\nバリア展開のユニオンバーストで味方を堅固に守護する。", "ミサト（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 182, 113601, 113601, 113601, 0, 5, 2, 450, 12, 1, "2020/08/15 15:00:00", 5, 0, "じゅん", 113601, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】前衛で、業火を従え悪を討つ真夏の騎士団長。\n敵単体にダメージを与えつつ、攻撃力を高めるユニオン\nバーストや、火傷を与えるスキルを操り敵を焼き尽くす。", "ジュン（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 530, 113701, 113701, 113701, 0, 7, 1.92, 450, 12, 2, "2020/09/03 19:00:00", 7, 0, "あかり", 113701, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】中衛で、魔法攻撃をお見舞いする双子の妹天使。\n効果時間が短い分、絶大な効果の強化魔法で自身の攻撃力\nを大きく高め、威力抜群の単体魔法で敵を一掃する。", "アカリ（エンジェル）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 531, 113801, 113801, 113801, 0, 6, 2.34, 450, 12, 2, "2020/09/19 15:00:00", 6, 0, "より", 113801, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】中衛で、補助魔法で味方を助ける双子の姉天使。\n防御力を大幅に高めつつ、対象の味方に敵の注意を引か\nせるなど、特殊で強力なスキルを駆使し敵を翻弄する。", "ヨリ（エンジェル）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 152, 113901, 113901, 113901, 0, 2, 2.375, 450, 12, 1, "2025/10/24 12:00:00", 2, 0, "つむぎ", 113901, 0, "2025/10/31 11:59:59", 3, 1, 0, 0, "【物理】前衛で敵の物理攻撃を妨害する吸血鬼テーラー。\n挑発と物理無効バリア、さらに最も物理攻撃力が高い敵を\n狙った妨害スキルによって、鉄壁の防御を織り上げる。", "ツムギ（ハロウィン）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 375, 114001, 114001, 114001, 0, 4, 1.965, 450, 12, 1, "2020/10/15 15:00:00", 4, 0, "れい", 114001, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】中衛で、手負いの敵を死に誘う、幽雅の剣士。\nＨＰが50％未満の敵に対し放つと、威力が大アップする\n範囲攻撃を繰り出し負傷した敵の戦意を一気に叩き折る。", "レイ（ハロウィン）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 186, 114101, 114101, 114101, 0, 1, 2.295, 450, 12, 1, "2022/07/19 8:00:00", 1, 0, "まつり", 114101, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【物理】前衛で鋭爪を突き立てるハロウィン騎士見習い。\nユニオンバーストの使用回数に応じて強化されるスキルで\n与えるダメージと行動速度をアップさせ、敵を斬り裂く。", "マツリ（ハロウィン）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 528, 114201, 114201, 114201, 0, 4, 2.24, 450, 12, 1, "2020/10/31 12:00:00", 4, 0, "もにか", 114201, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】中衛で愛と希望の力を胸に指揮を執る魔法提督。\nユニオンバーストで敵単体の物理防御力を下げ、範囲内の\n味方の物理攻撃力アップスキルで、一気に戦況を決める。", "モニカ（マジカル）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 402, 114301, 114301, 114301, 0, 4, 2, 450, 2, 1, "2020/11/21 15:00:00", 4, 0, "とも", 114301, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】中衛で正義の力を魔法にのせて戦う魔法剣士。\n自身の物理攻撃力を魔法攻撃力に加える魔法少女の力と、\nたゆまぬ努力で獲得した剣技で、華麗な魔法攻撃を放つ。", "トモ（マジカル）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 189, 114401, 114401, 114401, 0, 5, 2, 450, 2, 1, "2025/12/21 12:00:00", 5, 0, "あきの", 114401, 0, "2025/12/31 11:59:59", 3, 1, 0, 0, "【物理】前衛で味方のサポートを力に戦う、聖夜の令嬢。\nステータスアップ効果を受けると増加する【聖夜の煌き】\nでスキルを大きく強化し、聖夜を彩る強烈な一撃を放つ。", "アキノ（クリスマス）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 150, 114501, 114501, 114501, 0, 4, 2.09, 450, 3, 1, "2020/12/21 15:00:00", 4, 0, "されん", 114501, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】前衛で、光を操り味方を守る聖夜のサレンママ。\n敵の攻撃を防ぎ、ダメージを与えるユニオンバーストや、\nダメージを与えつつ回復するスキルで、攻守双方を担う。", "サレン（クリスマス）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 408, 114601, 114601, 114601, 0, 5, 2.09, 450, 2, 1, "2022/09/17 15:00:00", 5, 0, "ゆかり", 114601, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【物理】中衛で物理キャラを支援し戦う聖夜の元聖騎士。\n魔法攻撃力の高い敵単体のＴＰ減少や周囲の味方の魔法\n防御力アップスキルで、対魔法戦で無類の輝きを放つ。", "ユカリ（クリスマス）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 138, 114701, 114701, 114701, 0, 31, 2, 450, 2, 1, "2022/10/16 15:00:00", 2, 0, "むいみ", 114701, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【物理】前衛で、新風纏う「天楼覇断剣」を振るう少女。\n皆より一足遅れて突撃し、敵の前衛を吹き飛ばした後、\n強化した範囲物理攻撃で、ダンゴになった敵を斬り払う。", "ムイミ（ニューイヤー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 562, 115001, 115001, 115001, 0, 21, 2.07, 450, 2, 2, "2026/01/15 12:00:00", 7, 0, "ねねか", 115001, 0, "2026/01/31 11:59:59", 3, 1, 0, 0, "【魔法】中衛で艶やかな晴れ着を身に纏う『変貌大妃』。\n味方の魔法攻撃力アップやＨＰ、ＴＰを回復させるスキル\nで攻守にわたってサポートし苛烈な戦況でも勝利に導く。", "ネネカ（ニューイヤー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 533, 115501, 115501, 115501, 0, 2, 2, 450, 1, 1, "2026/07/15 12:00:00", 2, 0, "こっころ", 115501, 0, "2026/07/31 11:59:59", 3, 1, 0, 0, "【物理】中衛で、尊き儀装束を纏うエルフの里の巫女。\n自分の攻撃力を強化し、さらにＴＰ回復で攻撃の手数を\n増やす。クリティカル時の猛攻で仲間を守る剣となる。", "コッコロ（儀装束）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 578, 115601, 115601, 115601, 0, 7, 1.97, 450, 7, 2, "2022/11/17 15:00:00", 7, 0, "ゆい", 115601, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【魔法】中衛で精霊術を操り味方を支える儀装の魔法士。\n複数の物理攻撃力の強化スキルで味方を攻撃支援しつつ\n強力な回復スキルで、前線を整えバトルを掌握する。", "ユイ（儀装束）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 738, 115701, 115701, 115701, 0, 7, 2.27, 450, 9, 2, "2021/02/23 15:00:00", 7, 0, "かすみ", 115701, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】後衛で、敵の防御力を削ぎ取る渚の名探偵。\n攻撃力が高い敵に目標を定めて防御力を下げつつ、\n味方を強化するスキルで、どんな難事件も解決へと導く。", "カスミ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 173, 115801, 115801, 115801, 0, 4, 2.27, 450, 5, 1, "2022/12/19 15:00:00", 4, 0, "りま", 115801, 116101, "2030/12/31 15:00:00", 1, 1, 0, 0, "【物理】前衛の魔法の果実でお姫様姿になった恋乙女。\n獣の姿からユニオンバーストで一定時間、人の姿に変身し\n味方全体の攻撃力アップスキルで、火力の底上げをする。", "リマ（シンデレラ）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 166, 115901, 115901, 115901, 0, 5, 2.27, 450, 4, 1, "2021/03/03 19:00:00", 5, 0, "まこと", 115901, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】前衛で、華装に身を包み流麗な剣舞を舞う狼娘。\n周囲の味方の数に応じて、スキルの威力と物理攻撃力\nアップのスキル効果が上がり、鼓舞激励の一斬を振るう。", "マコト（シンデレラ）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 645, 116001, 116001, 116001, 0, 7, 2.27, 450, 9, 2, "2021/03/22 15:00:00", 7, 0, "まほ", 116001, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】後衛から、優雅に味方を支援するマホ先生。\n物理攻撃をする味方の攻撃力アップや、ＴＰを回復するス\nキルで、しゃなりしゃなりと戦況を変える。", "マホ（シンデレラ）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 184, 116201, 116201, 116201, 0, 2, 2.125, 450, 2, 1, "2021/04/15 15:00:00", 2, 0, "くろえ", 116201, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】前衛で疾風の如く駆け抜ける、ダウナー女子。\n特定回数ダメージを与えるたびＴＰを全回復するスキルと\n発動ごとに攻撃力アップのスキルで勝利のテープを掴む。", "クロエ（聖学祭）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 223, 116301, 116301, 116301, 0, 32, 2.295, 450, 2, 1, "2021/03/31 12:00:00", 1, 0, "ちえる", 116301, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】前衛で聖学祭を盛りアゲる、はぴちぇる系女子。\n攻撃ヒットのたびに【ちぇる】を貯め、威力が増すスキル\nと味方全体の物理攻撃力アップ効果のＵＢで勝利に導く。", "チエル（聖学祭）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 808, 116401, 116401, 116401, 0, 39, 2.27, 450, 2, 2, "2022/02/08 12:00:00", 7, 0, "ゆに", 116401, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】後衛から、仲間を啓蒙するユニちゃんズの才媛。\n自分以外の味方全員の物理・魔法両方の攻撃力アップと\nクリティカル時のダメージアップで皆を勝利へと導く。", "ユニ（聖学祭）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 252, 116501, 116501, 116501, 0, 3, 2.295, 450, 17, 1, "2021/04/30 12:00:00", 3, 0, "いのり", 116501, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】前衛で威勢よく、まくしたてる口撃系ドラゴン。\n全体物理攻撃力アップのＵＢは、味方の防御力を下げる\n代わりにＨＰが多いほど効果を高め、味方を勝利に導く。", "イノリ（タイムトラベル）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 169, 116601, 116601, 116601, 0, 1, 2.295, 450, 17, 1, "2021/05/21 15:00:00", 1, 0, "かや", 116601, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】前衛で味方を勝利にナビする喧嘩屋ドラゴン族。\nユニオンバーストで自身の攻撃速度を極大アップさせ、\n物理攻撃力アップスキルのシナジーで拳の雨を降らせる。", "カヤ（タイムトラベル）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 527, 116701, 116701, 116701, 0, 33, 1.82, 450, 9, 1, "2021/05/31 12:00:00", 33, 0, "あおい", 116701, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】中衛で敵を妨害する、作業服姿のぼっちエルフ。\n友情の絆で結ばれた『マイフレンドくん』と放つＵＢは、\n敵の動きを阻み、物理防御力を劇的に下げる。", "アオイ（作業服）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 216, 116801, 116801, 116801, 0, 2, 2.295, 450, 8, 1, "2023/03/16 15:00:00", 2, 0, "たまき", 116801, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【物理】前衛でたい焼き器片手に悪を討つ売り子の猫娘。\n味方全体を物理攻撃力アップとＴＰ回復させ、ＵＢでさら\nに自分の攻撃力を特大強化し、驚異の威力を発揮する。", "タマキ（作業服）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 275, 116901, 116901, 116901, 0, 6, 2.065, 450, 8, 1, "2021/06/16 15:00:00", 6, 0, "みふゆ", 116901, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】前衛で、皆の盾となり進攻するバイトリーダー。\nバトル序盤は物理の攻防両方をスキルで強化。ＵＢ発動毎\nに自分のクリティカルをアップし猛烈な攻撃を繰り出す。", "ミフユ（作業服）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 407, 117001, 117001, 117001, 0, 3, 1.55, 450, 11, 1, "2026/08/26 12:00:00", 3, 0, "えりこ", 117001, 0, "2026/08/31 11:59:59", 3, 1, 0, 0, "【物理】中衛で、火花を纏い夕闇を彩る真夏の壊し屋。\n二つのスキルで物理防御力を下げ、ダメージ量に応じて\nクリティカル上昇が延長するＵＢで眼前の敵を粉砕する。", "エリコ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 163, 117101, 117101, 117101, 0, 5, 2, 450, 6, 1, "2021/07/15 12:00:00", 5, 0, "しずる", 117101, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】前衛で、堅牢に仲間を守る海辺のお姉ちゃん。\n物理防御力が高い程、効果が高まる複数のスキルを巧みに\n操り防御と補助役をしつつ範囲攻撃で攻撃役をもこなす。", "シズル（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 417, 117201, 117201, 117201, 0, 4, 2.09, 450, 10, 1, "2026/09/22 12:00:00", 4, 0, "のぞみ", 117201, 0, "2026/09/30 11:59:59", 3, 1, 0, 0, "【物理】中衛でみんなを応援する真夏のトップアイドル。\nすべてのスキルで味方全体の物理攻撃をサポートし、\nバトル中盤から味方全体のＴＰ回復で、皆を勝利に導く。", "ノゾミ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 520, 117301, 117301, 117301, 0, 7, 2.07, 450, 10, 2, "2021/08/15 15:00:00", 7, 0, "ちか", 117301, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】中衛で、守護の賛歌を捧げる夏海の歌姫。\n最序盤に味方の魔法防御を大幅に強化し、吸収バリアや\nＨＰ回復スキルで、如何なる猛攻からも味方を守る。", "チカ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 355, 117401, 117401, 117401, 0, 1, 2.42, 450, 10, 1, "2023/05/16 15:00:00", 1, 0, "つむぎ", 117401, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【物理】中衛で敵を引き寄せ陣形を崩す夕凪のテーラー。\n最も攻撃力の高い敵を、敵陣から自陣に引き寄せつつ\n束縛や行動速度ダウンを絡めたスキルで敵の自由を縛る。", "ツムギ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 552, 117501, 117501, 117501, 0, 5, 2.4, 450, 11, 1, "2021/09/03 19:00:00", 5, 0, "みつき", 117501, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】中衛で、戦況のすべてを見据える隻眼の闇医者。\nＨＰが低い敵を束縛し防御力ダウンスキルで仕掛けつつ\n呪詛の毎秒増加する継続ダメージで敵の命を刻々と蝕む。", "ミツキ（オーエド）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 798, 117601, 117601, 117601, 0, 7, 2, 450, 12, 2, "2021/09/13 12:00:00", 7, 0, "ゆき", 117601, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】後衛で、迷える皆を救う白衣を纏いし美の象徴。\n一番低い味方１キャラのＴＰを回復し、ＨＰ回復スキルで\n守り、魔法攻撃力アップのスキルで一気に攻め落とす。", "ユキ（オーエド）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 156, 117701, 117701, 117701, 0, 1, 2.17, 450, 4, 1, "2026/10/15 12:00:00", 1, 0, "かおり", 117701, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【物理】前衛の敵を追い詰める程、力を増す幽玄南国娘。\n敵の体力が少ない程、効果が高まる攻撃力アップスキルと\nダメージ量アップの攻撃スキルで、敵を逃さず仕留める。", "カオリ（ハロウィン）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 518, 117801, 117801, 117801, 0, 36, 2.25, 450, 12, 1, "2023/07/18 15:00:00", 36, 0, "にのん", 117801, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【物理】中衛で物理攻撃タイプの味方を強化するシノビ。\n味方の物理攻撃力アップや行動速度アップのスキル効果で\n味方全体の攻撃力を底上げし、勝利の笛を吹きならす。", "ニノン（ハロウィン）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 761, 117901, 117901, 117901, 0, 8, 1.97, 450, 15, 1, "2021/10/15 15:00:00", 8, 0, "すずな", 117901, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】後衛でアタッカーを狙う小悪魔カリスマモデル。\n誘惑状態だと威力アップの攻撃スキルや、ＴＰを奪い取る\n妨害スキルを放ち、物理攻撃力が最も高い敵を狙い撃つ。", "スズナ（ハロウィン）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 751, 118001, 118001, 118001, 0, 35, 1.97, 450, 0, 1, "2026/09/22 12:00:00", 35, 0, "くれじった", 118001, 0, "2026/09/30 11:59:59", 3, 1, 0, 0, "【物理】後衛で、攻撃と敵の弱体化の二役で輝く女商人。\n生ける金貨が詰まった財布を投げつける不意打ちや、\n金貨の嵐を巻き起こす攻撃で、相手の防御を大きく崩す。", "クレジッタ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 782, 118101, 118101, 118101, 0, 21, 2.07, 450, 19, 2, "2026/10/23 12:00:00", 7, 0, "らんふぁ", 118101, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【魔法】後衛で、美しい旋律を紡ぎ支援する幽寂の歌姫。\n味方の強化と敵の弱体化の両方面での補助を行い、さらに\n召喚した鉱石の飛竜との波状攻撃により敵を鎮圧する。", "ランファ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 730, 118201, 118201, 118201, 0, 0, 1.7, 450, 19, 2, "2026/10/23 12:00:00", 0, 0, "みそら", 118201, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【魔法】後衛で笑顔とともに破壊を振りまく溌溂少女★\n最大３体に着弾するスキルとＵＢは【PSI★チャージ】\n状態で魔防ダウン効果を追加し、邪魔者たちを殲滅する。", "ミソラ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 732, 118301, 0, 0, 0, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", 0, 0, "はつね", 118301, 0, "2030/12/31 15:00:00", 3, 1, 1, 180701, "", "ハツネ（ハツネ&シオリ）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 732, 118401, 0, 0, 0, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", 0, 0, "しおり", 118401, 0, "2030/12/31 15:00:00", 3, 1, 1, 180701, "", "シオリ（ハツネ&シオリ）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 787, 118501, 118501, 118501, 0, 37, 2, 450, 0, 2, "2021/10/19 12:00:00", 37, 0, "かりん", 118501, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【魔法】後衛で皆を支える、ギルド管理協会の職員さん。\n通常攻撃の代わりに味方の能力を高める魔法を掛け、\n味方の守護や敵への妨害など、完璧なサポートをこなす。", "カリン");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 826, 118601, 118601, 118601, 0, 0, 2, 450, 0, 2, "2024/08/10 21:00:00", 0, 0, "ねびあ", 118601, 0, "2030/12/31 15:00:00", 3, 1, 0, 0, "【魔法】後衛を飛び出し悪戯の限りを尽くす幻惑の妖精。\n敵陣を勝手気ままに飛び回り、敵の攻撃を空振りさせて、\nＵＢで４種の妨害効果をランダムに与え大混乱に陥れる。", "ネビア");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 714, 119001, 119001, 119001, 0, 7, 2.27, 450, 15, 2, "2021/11/03 19:00:00", 7, 0, "いお", 119001, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】後衛で魔法アタッカーを妨害する闇のせんせー。\n最も魔法攻撃力が高い敵を、誘惑とＴＰダウンで妨害し\nＴＰ回復スキルで味方を援護することで戦況を支配する。", "イオ（ノワール）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 143, 119101, 119101, 119101, 0, 26, 2.545, 450, 12, 2, "2021/11/16 12:00:00", 7, 0, "くうか", 119101, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】前衛で、猛攻をバリアで受けきる闇のドＭ娘。\n最も魔法攻撃力が高い味方の魔法攻撃力とクリティカルを\nアップさせ、魔法防御力ダウンスキルで敵を怯ませる。", "クウカ（ノワール）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 397, 119201, 119201, 119201, 0, 6, 2.19, 450, 5, 1, "2023/09/19 15:00:00", 6, 0, "まひる", 119201, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【物理】中衛で味方を支援し、守護する聖夜の牧場主。\n範囲内の敵をノックバックさせることで相手の隊列を崩し\n全体物理バリア展開と単体ＨＰ回復で激戦を勝利に導く。", "マヒル（クリスマス）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 762, 119301, 119301, 119301, 0, 8, 1.97, 450, 6, 1, "2021/12/22 12:00:00", 8, 0, "りの", 119301, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】後衛で、攻撃と支援を担う聖夜のアーチャー。\n物理攻撃力と物理クリティカルアップスキルで周囲を強化\nし、クリティカルで威力が増大するＵＢで敵を粉砕する。", "リノ（クリスマス）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 0, 119401, 0, 0, 0, 0, 0, 0, 0, 0, "2022/01/31 12:00:00", 5, 0, "ぺこりーぬ", 119401, 0, "2030/12/31 15:00:00", 1, 0, 0, 0, "", "ペコリーヌ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 0, 119501, 0, 0, 0, 6, 0, 0, 0, 0, "2022/01/31 12:00:00", 6, 0, "こっころ", 119501, 0, "2030/12/31 15:00:00", 1, 0, 0, 0, "", "コッコロ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 0, 119601, 0, 0, 0, 7, 0, 0, 0, 0, "2022/01/31 12:00:00", 7, 0, "きゃる", 119601, 0, "2030/12/31 15:00:00", 1, 0, 0, 0, "", "キャル");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 0, 119701, 0, 0, 0, 4, 0, 0, 0, 0, "2022/01/31 12:00:00", 4, 0, "しぇふぃ", 119701, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "", "シェフィ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 302, 119901, 119901, 119901, 0, 1, 2.17, 450, 14, 1, "2025/12/21 12:00:00", 1, 0, "みやこ", 119901, 0, "2025/12/31 11:59:59", 3, 1, 0, 0, "【物理】中衛で、味方をプリンで強化する幽霊聖少女。\n物理攻撃力と物理クリティカルアップのプリンパワーの\nフィールドで自分のスキルも強化し、猛攻を繰り出す。", "ミヤコ（クリスマス）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 190, 120001, 120001, 120001, 0, 5, 2.375, 450, 6, 1, "2026/03/16 10:00:00", 5, 0, "しずる", 120001, 0, "2026/03/31 11:59:59", 3, 1, 0, 0, "【物理】前衛で猛攻から味方を守護する闇のお姉ちゃん。\nバトル開始時の行動不能無効スキルで周囲の味方を守り、\n範囲を束縛するスキルで敵を牽制し、戦況を一変する。", "シズル（ノワール）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 0, 120101, 0, 0, 0, 7, 0, 0, 0, 0, "2015/04/01 15:00:00", 7, 0, "いお", 120101, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "", "イオ（ノワール）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 0, 120201, 0, 0, 0, 26, 0, 0, 0, 0, "2015/04/01 15:00:00", 7, 0, "くうか", 120201, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "", "クウカ（ノワール）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 0, 120301, 0, 0, 0, 7, 0, 0, 0, 0, "2015/04/01 15:00:00", 5, 0, "しずる", 120301, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "", "シズル（ノワール）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 465, 120401, 0, 0, 0, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", 0, 0, "みみ", 120401, 0, "2030/12/31 15:00:00", 3, 1, 1, 180801, "", "ミミ（リトルリリカル）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 465, 120501, 0, 0, 0, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", 0, 0, "みそぎ", 120501, 0, "2030/12/31 15:00:00", 3, 1, 1, 180801, "", "ミソギ（リトルリリカル）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 465, 120601, 0, 0, 0, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", 0, 0, "きょうか", 120601, 0, "2030/12/31 15:00:00", 3, 1, 1, 180801, "", "キョウカ（リトルリリカル）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 283, 120701, 120701, 120701, 0, 22, 1.84, 450, 1, 1, "2026/01/15 12:00:00", 4, 0, "しぇふぃ", 120701, 0, "2026/01/31 11:59:59", 3, 1, 0, 0, "【物理】前衛で、雪花舞う晴れ空をゆく新春氷竜少女。\nＵＢで顕現させる氷竜の牙で味方への強化スキルを高め\n自身の範囲攻撃技と共に苛烈な攻勢で敵陣を凍滅する。", "シェフィ（ニューイヤー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 193, 120801, 120801, 120801, 0, 22, 1.3, 450, 2, 1, "2023/10/16 15:00:00", 4, 0, "るか", 120801, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【物理】前衛で雪月花の舞を納める新春の姉御。\n攻撃を当てる度に増加する【剣の刻印】でＵＢとスキルの\n威力を上昇させ、目にも止まらぬ斬撃で敵を圧倒する。", "ルカ（ニューイヤー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 424, 120901, 120901, 120901, 0, 38, 1.425, 450, 12, 2, "2026/01/15 12:00:00", 3, 0, "いりや", 120901, 0, "2026/01/31 11:59:59", 3, 1, 0, 0, "【魔法】中衛で自らの血を代償に力を振るう新春吸血鬼。\n自身のＨＰを消費して放つ強力なスキルと、敵からＴＰを\n吸収するスキルを自在に操り、目の前の敵を撃滅する。", "イリヤ（ニューイヤー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 164, 121001, 121001, 121001, 0, 41, 2.25, 450, 1, 1, "2026/01/31 12:00:00", 5, 0, "ぺこりーぬ", 121001, 0, "2026/02/09 11:59:59", 3, 1, 0, 0, "【物理】前衛で、仲間との絆を力に変え戦う腹ペコ王女。\n敵のＨＰ状態で永続の物理攻撃力上昇と、短時間の特大\n攻撃力上昇＆自己ＴＰ回復を使い分け戦況を一変させる。", "ペコリーヌ（オーバーロード）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 588, 121101, 121101, 121101, 0, 42, 2.07, 450, 1, 2, "2026/01/31 12:00:00", 7, 0, "きゃる", 121101, 0, "2026/02/09 11:59:59", 3, 1, 0, 0, "【魔法】中衛で仲間との絆を力に変え戦うツンデレ猫娘。\n敵を妨害するスキルと、ＵＢで敵全体を恐慌状態にし既に\n恐慌状態の敵のＴＰをダウンさせ、全戦場を掌握する。", "キャル（オーバーロード）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 260, 121201, 121201, 121201, 0, 40, 1.55, 450, 6, 1, "2023/11/16 15:00:00", 4, 0, "らびりすた", 121201, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【物理】前衛で世界の理をすべて見つめる『迷宮女王』。\n味方を攻撃面で強化し、継続ＨＰ回復を全体に付与する\nスキルで戦線を整え、自身も圧倒的な力で敵を殲滅する。", "ラビリスタ（オーバーロード）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 731, 121301, 121301, 121301, 0, 3, 1.9, 450, 3, 1, "2022/03/03 19:00:00", 3, 0, "くるみ", 121301, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】後衛で、皆のため意を決し奮起する小さな女優。\n残りＨＰが多いほど物理攻撃力がアップし、物理攻撃無効\nバリアのスキルやＨＰ・ＴＰ継続回復で味方を支援する。", "クルミ（ステージ）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 742, 121401, 121401, 121401, 0, 7, 2.27, 450, 15, 2, "2022/03/15 15:00:00", 7, 0, "みさき", 121401, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】後衛で後ろの味方を強化する魔法少女の看板娘。\n後衛の味方をバリアとＴＰ継続回復で支援し、自分の魔法\n攻撃力に応じ強化される攻撃力アップスキルで鼓舞する。", "ミサキ（ステージ）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 590, 121501, 121501, 121501, 0, 6, 2, 450, 12, 1, "2026/03/31 12:00:00", 6, 0, "あゆみ", 121501, 0, "2026/04/15 11:59:59", 3, 1, 0, 0, "【物理】中衛で、闇夜に身を潜める神出鬼没の怪盗少女。\n敵の目の前から姿を消す隠密スキルや、遠くの敵に対する\nＴＰダウンスキルを駆使して、敵陣後方から瓦解させる。", "アユミ（怪盗）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 292, 121601, 121601, 121601, 0, 3, 1.425, 450, 17, 1, "2022/04/15 15:00:00", 3, 0, "いのり", 121601, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】前衛で闇に紛れ会心の一撃を放つ怪盗ドラゴン。\n隠密効果中、ダメージが大アップし必ずクリティカルする\nＵＢとスキルを駆使し安定したダメージを敵に叩き込む。", "イノリ（怪盗）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 421, 121701, 0, 0, 0, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", 0, 0, "あきの", 121701, 0, "2030/12/31 15:00:00", 3, 1, 1, 180901, "", "アキノ（アキノ＆サレン）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 421, 121801, 0, 0, 0, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", 0, 0, "されん", 121801, 0, "2030/12/31 15:00:00", 3, 1, 1, 180901, "", "サレン（アキノ＆サレン）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 293, 121901, 121901, 121901, 0, 5, 2.125, 450, 12, 2, "2022/05/15 15:00:00", 5, 0, "あんな", 121901, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】前衛で己を鼓舞し高めた魔力を放つ蒼海の冥姫。\n発動の度、攻撃力とクリティカル時ダメージが上昇する\nＵＢと自己犠牲を払う強力な範囲攻撃技で敵を撃滅する。", "アンナ（パイレーツ）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 380, 122001, 122001, 122001, 0, 3, 1.425, 450, 14, 1, "2022/05/03 19:00:00", 3, 0, "しのぶ", 122001, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】中衛で、彷徨える魂を解き放つ海星の霊能少女。\n攻撃の際、付与する【霊錨の刻印】を駆使し、ダメージ量\nアップのスキルと防御力ダウンのＵＢで敵を浄滅へ導く。", "シノブ（パイレーツ）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 731, 122101, 122101, 122101, 0, 35, 1.97, 450, 9, 1, "2024/04/18 15:00:00", 35, 0, "あおい", 122101, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【物理】後衛で百千の矢を放つ、ぼっちの山籠りエルフ。\n物理魔法無効バリアで耐え凌ぎ、敵全体への射撃と自分の\n間合いに入った敵への強力な弓雨の追撃で掃討する。", "アオイ（キャンプ）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 419, 122201, 122201, 122201, 0, 4, 1.84, 450, 8, 1, "2022/05/31 12:00:00", 4, 0, "ゆかり", 122201, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】中衛で最高の一杯を自然と共に愉しむ元聖騎士。\n【至福のひと時】が増えるほどに、味方の物理攻撃力や\nクリティカル時のダメージを強力に強化し、勝利を掴む。", "ユカリ（キャンプ）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 564, 122301, 122301, 122301, 0, 43, 1.425, 450, 0, 2, "2022/06/15 15:00:00", 43, 0, "うぁんぴぃ", 122301, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】中衛で、幼き竜と共に歩むさいきょーの吸血姫。\n味方全体の強化と、敵のＴＰを吸収するスキルで力を蓄え\nＵＢ発動後ベスと共闘し防御ダウンと強撃で攻勢に出る。", "ヴァンピィ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 264, 122401, 122401, 122401, 0, 1, 2.42, 450, 8, 1, "2024/06/17 15:00:00", 1, 0, "ひより", 122401, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【物理】前衛で皆にエールを送り鼓舞する真夏の元気娘。\n味方のＨＰを継続回復し行動速度アップの他、味方の数に\n応じてクリティカル強化と攻撃力を引き上げ勝利に導く。", "ヒヨリ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 250, 122501, 122501, 122501, 0, 4, 1.965, 450, 0, 1, "2026/08/26 12:00:00", 4, 0, "れい", 122501, 0, "2026/08/31 11:59:59", 3, 1, 0, 0, "【物理】前衛で水刃の加護を纏い水面を駆ける渚の剣士。\nクリティカル時のダメージを底上げしＵＢ発動の度、纏う\n【水刃の加護】で全スキルダメージを上げ、敵陣を穿つ。", "レイ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 554, 122601, 122601, 122601, 0, 7, 2.27, 450, 0, 2, "2022/07/15 15:00:00", 7, 0, "ゆい", 122601, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】中衛で、魔法キャラを補助する夜凪の魔法士。\n累積する攻撃強化スキルとＴＰ回復、物魔両面の無効\nバリアや継続ＨＰ回復で攻守共に味方を支え勝利へ導く。", "ユイ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 812, 122701, 122701, 122701, 0, 7, 1.92, 450, 0, 2, "2022/08/15 15:00:00", 7, 0, "きょうか", 122701, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】後衛で、難しい魔法の練習に励む海辺の優等生。\nランダムな敵に当たるスキルの威力は攻撃の際に付与する\n【バタフライシール】で増幅し、防御力もダウンさせる。", "キョウカ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 237, 122801, 122801, 122801, 0, 1, 2.295, 450, 0, 1, "2024/07/16 15:00:00", 1, 0, "みそぎ", 122801, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【物理】前衛で敵後方に花火を仕掛ける夜涼みの悪戯娘。\n敵の最前衛をスタンで足止めしつつ、最後衛を中心とした\nＵＢで狭範囲の敵を引き寄せ、ＴＰダウンで攻勢を阻む。", "ミソギ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 361, 122901, 122901, 122901, 0, 5, 2.25, 450, 0, 1, "2026/08/26 12:00:00", 5, 0, "みみ", 122901, 0, "2026/08/31 11:59:59", 3, 1, 0, 0, "【物理】中衛で巨大バルーンと跳ね回る夏色うさぎっこ。\nＵＢやスキルで全てのマルチターゲットに追加ダメージを\n与え、自己強化と防御力ダウンで強敵のブレイクを狙う。", "ミミ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 746, 123001, 123001, 123001, 0, 44, 2.27, 450, 0, 2, "2026/10/23 12:00:00", 44, 0, "あめす", 123001, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【魔法】後衛で、新たな姿で騎士の冒険を支える妖精。\nダメージカットや防御力アップ、無効バリアで味方を護り\nバリアを起点とする攻撃力とＴＰの支援で攻勢に転ずる。", "アメス");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 793, 123101, 123101, 123101, 0, 7, 1.795, 450, 0, 2, "2022/09/03 19:00:00", 7, 0, "まほ", 123101, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】後衛でぬいぐるみ達と大冒険に挑むマホ隊員。\n味方に付与する【ふわふわウール】は被ダメージ時に消費\nされＴＰを回復し、一気呵成の反撃で活路を切り拓く。", "マホ（エクスプローラー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 256, 123201, 123201, 123201, 0, 3, 1.425, 450, 0, 1, "2022/09/15 15:00:00", 3, 0, "あやね", 123201, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】前衛で、相棒と困難を越え猛進するアヤネ隊員。\n群る敵を二つの範囲攻撃で一気に捉え、周囲の味方の物理\n攻撃力とクリティカルアップで冒険を阻む壁を打ち崩す。", "アヤネ（エクスプローラー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 350, 123301, 123301, 123301, 0, 0, 1.62, 450, 0, 1, "2026/09/22 12:00:00", 1, 0, "ねあ", 123301, 0, "2026/09/30 11:59:59", 3, 1, 0, 0, "【物理】中衛で粘液を振りまくキイロいスライムギャル。\nスキルで敵全体の物理攻撃能力やＴＰ上昇を低下させ、\nＵＢでスライム化し全敵を攻撃しつつ無敵ボディを得る。", "ネア");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 0, 123401, 0, 0, 0, 5, 0, 0, 0, 0, "2015/04/01 15:00:00", 5, 0, "じゅん", 123401, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "", "ジュン（キャンプ）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 583, 123501, 123501, 123501, 0, 6, 2.34, 450, 0, 1, "2024/09/17 15:00:00", 6, 0, "りん", 123501, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【物理】中衛で敵を悪戯で翻弄する恐怖のキョンシー娘。\n最も魔法攻撃力が高い敵に急襲を仕掛け、ＴＰ減少や魔法\n攻撃力ダウン、スタン等の妨害スキルで機先を制する。", "リン（ハロウィン）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 262, 123601, 123601, 123601, 0, 4, 1.965, 450, 0, 1, "2026/10/15 12:00:00", 4, 0, "とも", 123601, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【物理】前衛で、同志と力を合わせ共に戦う夜廻り剣士。\n自分と物理攻撃力が最も高い味方１キャラの攻撃力を大幅\nに上昇させ、目にもとまらぬ剣技で不届き者を成敗する。", "トモ（ハロウィン）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 741, 123701, 123701, 123701, 0, 21, 2.07, 450, 0, 2, "2022/10/15 15:00:00", 7, 0, "ななか", 123701, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】後衛で、オタ活に精を出すハロウィン魔法少女。\nＨＰ回復量ダウンで敵の戦略を崩し、ダメージフィールド\nと対象の数で火傷の威力を増す熱狂の炎が敵を包み込む。", "ナナカ（ハロウィン）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 238, 123801, 123801, 123801, 0, 1, 2.295, 450, 0, 1, "2026/11/16 12:00:00", 1, 0, "くりすてぃーな", 123801, 0, "2026/11/30 11:59:59", 3, 1, 0, 0, "【物理】前衛で、戦場を跳ね回るラビット姿の誓約女君。\n物理攻撃を全て回避するスキルと攻撃力の強化で敵陣に\n単身特攻をかけ、ＵＢの範囲攻撃で敵を内から薙ぎ倒す。", "クリスティーナ（ワイルド）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 183, 123901, 123901, 123901, 0, 2, 2.125, 450, 0, 1, "2022/11/15 15:00:00", 2, 0, "まつり", 123901, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】前衛で母製の鎧を纏い気合い上々の獣人族騎士。\n自分のＨＰが低いほど与えるダメージと無効バリアの耐久\n力を高め、防御力ダウンと永続攻撃アップで活路を拓く。", "マツリ（ワイルド）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 438, 124001, 124001, 124001, 0, 7, 2.07, 450, 0, 2, "2025/12/21 12:00:00", 7, 0, "あかり", 124001, 0, "2025/12/31 11:59:59", 3, 1, 0, 0, "【魔法】中衛で、聖夜の街に幸せを運ぶ双子の妹サンタ。\n自分の魔法攻撃力に応じて効果が上がる味方全体への攻撃\n力強化に加え、単体特大魔法攻撃で勝利の旋律を奏でる。", "アカリ（クリスマス）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 433, 124101, 124101, 124101, 0, 6, 1.965, 450, 0, 2, "2024/11/16 15:00:00", 6, 0, "より", 124101, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【魔法】中衛で、光を灯し幸せを届ける双子の姉サンタ。\n最も近い１キャラの魔法攻撃力や行動速度アップ、ＴＰの\n回復に加え、全員を支援するスキルで聖夜の勝利を飾る。", "ヨリ（クリスマス）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 144, 124201, 124201, 124201, 0, 5, 2.07, 450, 0, 1, "2022/12/23 12:00:00", 5, 0, "じゅん", 124201, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】前衛で、味方を庇護し祝福する聖白の騎士団長。\nスキルで後方の味方の攻撃能力を強化、ＴＰを回復させ、\n防御力ダウンと自分のＨＰを回復するＵＢで勝機を掴む。", "ジュン（クリスマス）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 577, 124301, 0, 0, 0, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", 0, 0, "あん", 124301, 0, "2030/12/31 15:00:00", 3, 1, 1, 181001, "", "アン（アン＆グレア）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 577, 124401, 0, 0, 0, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", 0, 0, "ぐれあ", 124401, 0, "2030/12/31 15:00:00", 3, 1, 1, 181001, "", "グレア（アン＆グレア）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 707, 124501, 124501, 124501, 0, 21, 2.07, 450, 0, 2, "2026/01/15 12:00:00", 7, 0, "ほまれ", 124501, 0, "2026/01/31 11:59:59", 3, 1, 0, 0, "【魔法】後衛で、魔力を笑顔に隠す晴れ着姿の龍の首魁。\n自分の攻撃強化とＴＰ回復をし、ＵＢで放つ曙光の落涙は\n敵数で威力と防御力の減少量を上げ、全ての災厄を祓う。", "ホマレ（ニューイヤー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 698, 124601, 124601, 124601, 0, 21, 2.44, 450, 0, 2, "2026/01/15 12:00:00", 7, 0, "みさと", 124601, 0, "2026/01/31 11:59:59", 3, 1, 0, 0, "【魔法】後衛で真心重ねて味方をもてなす仲居姿の先生。\n全スキルで味方の物理攻撃力とクリティカル能力を上げ、\n魔防やＴＰ上昇の支援とＨＰ、ＴＰの回復で万福を願う。", "ミサト（ニューイヤー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 590, 124701, 124701, 124701, 0, 46, 2.24, 450, 0, 1, "2024/12/16 15:00:00", 7, 0, "みつき", 124701, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【物理】中衛で、振袖姿で旅館に手を貸す隻眼の闇医者。\n朧ろ状態にした敵への攻撃時、スキルのダメージや防御力\nのダウン値が上昇し、紫煙に捉えた敵を艶然と討ち取る。", "ミツキ（ニューイヤー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 423, 124801, 124801, 124801, 0, 0, 2.14, 450, 0, 1, "2026/01/31 12:00:00", 4, 0, "のぞみ", 124801, 0, "2026/02/09 11:59:59", 3, 1, 0, 0, "【物理】中衛で、未来を信じ希望を灯すトップアイドル。\nバトル開始時に物理キャラのＴＰ特大回復と敵の永続物防\nダウンで加勢し、物理攻撃強化とＴＰ回復で勝利へ導く。", "ノゾミ（リベレイター）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 170, 124901, 124901, 124901, 0, 0, 1.965, 450, 0, 1, "2025/01/16 15:00:00", 1, 0, "かや", 124901, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【物理】前衛で先陣を切り未来を掴む喧嘩屋ドラゴン族。\n初弾が大幅強化するスキルで自分の攻撃力とＴＰを大きく\n高め、威力を増したＵＢで先制し群がる敵を薙ぎ払う。", "カヤ（リベレイター）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 221, 125001, 125001, 125001, 0, 0, 1.965, 450, 0, 1, "2026/01/31 12:00:00", 5, 0, "むいみ", 125001, 0, "2026/02/09 11:59:59", 3, 1, 0, 0, "【物理】前衛で、相棒と共に明日へと進む大悪党の少女。\n自己強化や物防ダウンを駆使するムイミと、ＵＢ後に一定\n時間共闘するオクトーの追撃で、輝く未来を取り戻す。", "ムイミ（リベレイター）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 825, 125101, 125101, 125101, 0, 47, 2.24, 450, 0, 1, "2023/03/03 19:00:00", 8, 0, "たまき", 125101, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】後衛から客を癒しもてなす猫カフェ店員の猫娘。\n物攻の高いキャラの傍で周囲の物攻アップやＨＰとＴＰを\n回復し、周囲の味方数で強化される攻撃で敵を一掃する。", "タマキ（カフェ）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 463, 125201, 125201, 125201, 0, 4, 1.965, 450, 0, 1, "2023/03/10 12:00:00", 4, 0, "もにか", 125201, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】中衛で、駄菓子を振舞い福を蒔く猫カフェ店員。\n攻撃を３回受けるまで味方全体の物理攻撃力を極大アップ\nさせ、２種の物防ダウンスキルで序盤を一気に加勢する。", "モニカ（カフェ）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 752, 125301, 125301, 125301, 0, 6, 2.07, 450, 0, 1, "2026/03/31 12:00:00", 6, 0, "こっころ", 125301, 0, "2026/04/15 11:59:59", 3, 1, 0, 0, "【物理】後衛で、わんわんと一緒の新緑レンジャー少女。\n自分の攻撃力に応じて強化される物理攻撃支援スキルや\nＨＰ継続回復、バリアで周囲を支え、絆の勝利へと導く。", "コッコロ（レンジャー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 710, 125401, 125401, 125401, 0, 8, 2.09, 450, 0, 1, "2023/04/10 12:00:00", 8, 0, "しおり", 125401, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】後衛で、相棒と共に山を駆ける新米レンジャー。\nスキルで自分の攻撃力とクリティカル時のダメージを上げ\nＴＰを回復し、ダメージと防御力ダウンで敵を追い込む。", "シオリ（レンジャー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 443, 125501, 125501, 125501, 0, 50, 1.92, 450, 0, 2, "2026/05/22 12:00:00", 7, 0, "じーた", 125501, 0, "2026/05/31 11:59:59", 3, 1, 0, 0, "【魔法】中衛で、他の術者と魔力を束ねる究竟の魔導士。\n味方への魔法攻撃支援とＴＰ回復に加え、敵陣の攻防両面\nの弱体化で戦況を整え、自らも強力な攻撃魔法を放つ。", "ジータ（ウォーロック）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 267, 125601, 125601, 125601, 0, 0, 2.09, 450, 0, 1, "2026/05/22 12:00:00", 51, 0, "びから", 125601, 0, "2026/05/31 11:59:59", 3, 1, 0, 0, "【物理】前衛で夢と希望とネズ耳を届ける鼠神宮の巫女。\n周囲の味方の物理攻撃支援、ＴＰ上昇アップと回復で援護\nし、自身の無敵化で敵の隙を突き鋭い金牙の一撃を放つ。", "ビカラ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 579, 125701, 125701, 125701, 0, 9, 2.24, 450, 0, 2, "2025/04/16 15:00:00", 7, 0, "かりん", 125701, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【魔法】中衛で森羅万象を究め味方を支援する錬金術師。\n物理、魔法の属性を問わない敵の弱体化と味方の強化に加\nえ、スキルによる高頻度のＨＰ回復で盤石な戦局を築く。", "カリン（アルケミスト）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 464, 125801, 125801, 125801, 0, 0, 2.09, 450, 0, 1, "2023/04/17 12:00:00", 3, 0, "りり", 125801, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】中衛で、黒羽の力を使い空を制する嘆鎌の少女。\nバトル開始時に、敵の範囲攻撃を躱す【飛行】状態となり\n生成したシャドウと共に、眼前の敵を一薙ぎに斬り払う。", "リリ（フォールン）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 0, 125901, 0, 0, 0, 1, 0, 0, 0, 0, "2015/04/01 15:00:00", 1, 0, "かや", 125901, 0, "2030/12/31 15:00:00", 3, 1, 0, 0, "", "カヤ（リベレイター）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 406, 126001, 126001, 126001, 0, 0, 2.09, 450, 0, 1, "2023/10/31 12:00:00", 0, 0, "くりあ", 126001, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】中衛から、我が身を盾に味方を守る隠棘の少女。\nバトル開始時【飛行】し、最もＨＰの低い味方をかばい、\n味方のＨＰに応じて強化されるスキルで敵を牽制する。", "クリア（フォールン）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 480, 126101, 126101, 126101, 0, 53, 2.09, 450, 0, 2, "2023/11/15 15:00:00", 44, 0, "ぷれしあ", 126101, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】中衛で、マイペースに味方を支える破杖の少女。\n【飛行】し、クリティカルの強化やＨＰ・ＴＰ回復で味方\nを支援し、魔法攻撃力を加えた物理攻撃で敵を平らげる。", "プレシア（フォールン）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 568, 126201, 126201, 126201, 0, 3, 2.09, 450, 0, 2, "2026/06/22 12:00:00", 3, 0, "いりや", 126201, 0, "2026/06/30 11:59:59", 3, 1, 0, 0, "【魔法】中衛で、眷属と永久の血盟を誓う月下の吸血鬼。\nＵＢで眷属を２体喚び、味方への攻撃支援や行動速度上昇\nで強化し、眷属と共に見舞う猛攻で前途を阻む敵を討つ。", "イリヤ（儀装束）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 456, 126301, 126301, 126301, 0, 9, 2.07, 450, 0, 2, "2023/06/15 15:00:00", 7, 0, "ゆき", 126301, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】中衛で、闇色の儀装束を纏う「美を統べる者」。\nステータスアップ効果を受け【美貌】を増し、魔法攻撃力\nダウンや味方の強化、ＴＰ回復の効果を高めて解き放つ。", "ユキ（儀装束）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 373, 126401, 126401, 126401, 0, 1, 2.09, 450, 0, 1, "2026/10/23 12:00:00", 1, 0, "くろーちぇ", 126401, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【物理】中衛で着脱可能な鉄腕を放つ機械人族のロボ娘。\nＵＢ発動で【フルチャージ】状態になり、【バッテリー】\nが切れるまで強化スキルを連発し、一帯を超速圧砕する。", "クローチェ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 740, 126501, 126501, 126501, 0, 0, 1.965, 450, 0, 2, "2026/10/23 12:00:00", 7, 0, "らいらえる", 126501, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【魔法】後衛で優美にほほ笑むジオ・テオゴニアの姫君。\n開始時に発動する【界雷】で、敵味方に影響を与えつつ、\n魔法防御ダウンと強力なダメージスキルで裁きを下す。", "ライラエル");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 650, 126601, 126601, 126601, 0, 7, 2.04, 450, 0, 2, "2026/07/15 12:00:00", 7, 0, "ねねか", 126601, 0, "2026/07/31 11:59:59", 3, 1, 0, 0, "【魔法】後衛で、涼しげに微笑む夏色姿の『変貌大妃』。\nスキルで味方を大幅に強化し、最も魔法攻撃力が高い味方\nの魔法攻撃力を写し取った攻撃力で、強力なＵＢを放つ。", "ネネカ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 224, 126701, 126701, 126701, 0, 5, 1.965, 450, 0, 1, "2025/06/17 15:00:00", 5, 0, "あきの", 126701, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【物理】前衛で、優雅なバカンスを過ごす夕映えの令嬢。\n敵が魔法攻撃をする場合に効果を大幅に上げる２種の範囲\n攻撃と攻防両面の支援スキルで、盛夏の勝鬨を上げる。", "アキノ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 159, 126801, 126801, 126801, 0, 5, 1.97, 450, 0, 1, "2023/07/15 15:00:00", 5, 0, "ゆかり", 126801, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】前衛で、夏の麦しゅわを嗜むビーチの元聖騎士。\n敵単体にダメージを与えながら、周囲の味方への魔法無効\nバリア付与と魔防アップで守りを固めて勝利の波に乗る。", "ユカリ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 682, 126901, 126901, 126901, 0, 21, 1.965, 450, 0, 2, "2026/08/26 12:00:00", 7, 0, "らんふぁ", 126901, 0, "2026/08/31 11:59:59", 3, 1, 0, 0, "【魔法】後衛で、密やかな潮騒に耳を傾ける晩陽の歌姫。\n魔法クリティカルの極大アップを筆頭に攻防両面で周囲の\n味方を強化し、さらに自身もＵＢで数多の敵を退かせる。", "ランファ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 133, 127001, 127001, 127001, 0, 52, 1.97, 450, 0, 1, "2025/07/16 15:00:00", 2, 0, "くうか", 127001, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【物理】前衛で新たな刺激を追い求める水着姿のドＭ娘。\n自分のＨＰが下がるほど効果量が上昇するスキルの物理攻\n撃力アップとＵＢのダメージで、勝利の大海へ飛び込む。", "クウカ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 255, 127101, 127101, 127101, 0, 46, 2.09, 450, 0, 1, "2026/08/26 12:00:00", 5, 0, "しのぶ", 127101, 0, "2026/08/31 11:59:59", 3, 1, 0, 0, "【物理】前衛で、穏やかな水面に揺蕩う夜光の霊能少女。\n召喚した親父に敵の攻撃を引き付けさせつつ、シノブ自身\nの攻撃性能強化と防御ダウンを扱い、敵を冥海へと誘う。", "シノブ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 804, 127201, 127201, 127201, 0, 7, 2.09, 450, 0, 2, "2025/09/16 15:00:00", 7, 0, "きゃる", 127201, 0, "2025/09/30 11:59:59", 3, 1, 0, 0, "【魔法】後衛で、制服姿に胸を高鳴らせるアオハル猫娘。\n攻防両面のサポートに加え行動速度アップとＴＰ回復で味\n方を支援し、最も遠くの敵を狙うＵＢで輝く勝利を得る。", "キャル（編入生）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 750, 127301, 127301, 127301, 0, 8, 2.09, 450, 0, 1, "2023/09/15 15:00:00", 8, 0, "すずな", 127301, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】後衛でもにカワ制服を着こなすカリスマモデル。\nクリティカル時に味方を強化するスキルや、追加ダメージ\nが発生するＵＢによって青春の一ページを切り取る。", "スズナ（編入生）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 0, 127401, 0, 0, 0, 1, 0, 0, 0, 0, "2015/04/01 15:00:00", 1, 0, "びから", 127401, 0, "2030/12/31 15:00:00", 3, 1, 0, 0, "", "ビカラ（コラボ）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 304, 127501, 127501, 127501, 0, 4, 2.09, 450, 0, 1, "2026/10/15 12:00:00", 4, 0, "されん", 127501, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【物理】中衛で、優艶に炎と踊り舞う情熱のサレンママ。\n物理攻撃から味方を守り、【炎舞の刻印】の数に応じて効\n果の上がる物攻アップとＴＰ回復で皆を奮い立たせる。", "サレン（サラサリア）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 157, 127601, 127601, 127601, 0, 4, 1.965, 450, 0, 1, "2023/10/15 15:00:00", 4, 0, "るか", 127601, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】前衛で、空飛ぶ絨毯で巡り回るオアシスの姉御。\n自分の物防を大幅に高めて敵を挑発するスキルと敵のＴＰ\nとＴＰ上昇をダウンさせるＵＢで、爽やかに勝利を掴む。", "ルカ（サラサリア）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 693, 127701, 127701, 127701, 0, 48, 1.965, 450, 0, 2, "2024/10/10 12:00:00", 6, 0, "りんど", 127701, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】後衛で、メイド業に奔走する双子ドラゴンの姉。\nＵＢのフィールド展開中は攻撃、防御、ＴＰ回復と多彩な\n支援スキルの効果が再発動し味方を手厚くサポートする。", "リンド");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 706, 127801, 127801, 127801, 0, 47, 1.965, 450, 0, 2, "2024/10/18 12:00:00", 7, 0, "うるむ", 127801, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】後衛で、文句を言いつつ働く双子ドラゴンの妹。\nダメージと魔法防御力ダウンを両立するスキルを持つが、\n目を離すと【サボりの誘惑】に負け、手を抜いてしまう。", "ヴルム");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 372, 127901, 127901, 127901, 0, 5, 1.965, 450, 0, 2, "2025/12/21 12:00:00", 5, 0, "ぺこりーぬ", 127901, 0, "2025/12/31 11:59:59", 3, 1, 0, 0, "【魔法】中衛でみんなに笑顔を届ける腹ペコサンタ王女。\n前線で敵の攻撃を耐えながら範囲内の味方の防御サポート\nと敵の防御ダウンまでこなし、聖夜に勝利の輝きを灯す。", "ペコリーヌ（クリスマス）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 723, 128001, 128001, 128001, 0, 35, 2.09, 450, 0, 1, "2023/12/15 15:00:00", 35, 0, "くれじった", 128001, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】後衛で、甘美なひと時を堪能する聖夜の女商人。\n最も遠い味方へのＴＰ回復や、初弾に追加効果のある攻撃\nで敵の弱体化と味方の強化を行い、勝利の舞台を整える。", "クレジッタ（クリスマス）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 580, 128101, 0, 0, 0, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", 0, 0, "しずる", 128101, 0, "2030/12/31 15:00:00", 3, 1, 1, 181101, "", "シズル（シズル&リノ）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 580, 128201, 0, 0, 0, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", 0, 0, "りの", 128201, 0, "2030/12/31 15:00:00", 3, 1, 1, 181101, "", "リノ（シズル&リノ）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 191, 128301, 128301, 128301, 0, 38, 2.09, 450, 0, 1, "2026/01/16 15:00:00", 3, 0, "いのり", 128301, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【物理】前衛で相手をからかうお調子者の年神ドラゴン。\n敵全体を挑発し、敵の妨害スキルにカウンターして前方の\n敵すべてをスタンさせるスキルで戦局を引っ掻き回す。", "イノリ（ニューイヤー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 801, 128401, 128401, 128401, 0, 21, 2.09, 450, 0, 2, "2026/01/15 12:00:00", 7, 0, "はつね", 128401, 0, "2026/01/31 11:59:59", 3, 1, 0, 0, "【魔法】後衛で特別な景色を共にする初夢超能力ガール。\n敵が物理攻撃を行う場合、攻撃性能の強化に加えて複数の\n弱体効果が追加され、攻守ともに味方を支援し敵を掃う。", "ハツネ（ニューイヤー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 739, 128501, 128501, 128501, 0, 21, 2.09, 450, 0, 2, "2026/01/15 12:00:00", 7, 0, "かすみ", 128501, 0, "2026/01/31 11:59:59", 3, 1, 0, 0, "【魔法】後衛で、絵馬に秘めた願いを祷る新年の名探偵。\n敵と味方の数で効果量が上昇するダメージと攻撃力支援に\n加え、２種類の回復スキルを使いこなして勝利を願う。", "カスミ（ニューイヤー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 0, 128601, 0, 0, 0, 1, 0, 0, 0, 0, "2015/04/01 15:00:00", 1, 0, "りり", 128601, 0, "2030/12/31 15:00:00", 3, 1, 0, 0, "", "リリ（フォールン）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 226, 128701, 128701, 128701, 0, 0, 2.09, 450, 0, 1, "2026/01/31 12:00:00", 1, 0, "ひより", 128701, 0, "2026/02/09 11:59:59", 3, 1, 0, 0, "【物理】前衛で、煌炎宿し希望を振りまく覚醒の元気娘。\n放つ炎は敵を攻守ともに弱化させて同時に味方を鼓舞し、\n２種のＴＰ回復効果で攻勢を絶やさず勝利を呼び込む。", "ヒヨリ（アストラル）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 194, 128801, 128801, 128801, 0, 0, 1.965, 450, 0, 1, "2025/08/16 15:00:00", 4, 0, "れい", 128801, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【物理】前衛で、旋風を纏い未来へ駆ける覚醒の剣士。\n目にも止まらぬ速さの剣技で敵を吹き飛ばしスタンさせ、\n仲間の守りを固めるスキルを駆使し勝利の道を切り開く。", "レイ（アストラル）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 772, 128901, 128901, 128901, 0, 0, 2.09, 450, 0, 2, "2026/01/31 12:00:00", 7, 0, "ゆい", 128901, 0, "2026/02/09 11:59:59", 3, 1, 0, 0, "【魔法】後衛で、願いを力に極光を放つ覚醒の魔法士。\n自分を強化しながら高火力魔法を絶えず撃ち込み、バリア\nを起点とした味方への攻撃支援スキルで勝利を手にする。", "ユイ（アストラル）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 800, 129001, 129001, 129001, 0, 0, 2.09, 450, 0, 2, "2026/10/23 12:00:00", 7, 0, "えりす", 129001, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【魔法】後衛で、眠りから目覚め美しく咲き誇る黒薔薇。\n終焉を超えし【回帰の薔薇】と、行動速度アップを始めと\nした多種の攻防支援で味方を強化し、新たな未来を掴む。", "エリス");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 708, 129301, 129301, 129301, 0, 7, 2.09, 450, 0, 1, "2026/03/16 10:00:00", 7, 0, "ゆに", 129301, 0, "2026/03/31 11:59:59", 3, 1, 0, 0, "【物理】後衛で、退廃的な冬の学びに溺れる水際の才媛。\n物理攻撃の強化、回復、行動速度アップで味方を支援し、\nＵＢで得た【水際の安寧】を死守するため膂力を振るう。", "ユニ（ウィンター）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 188, 129401, 129401, 129401, 0, 2, 2.09, 450, 0, 1, "2024/03/18 12:00:00", 2, 0, "くろえ", 129401, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】前衛で、水面に映る神速のダウナー系水着女子。\n攻撃を当てる度に敵に付与する【水月】の数に応じて物防\nダウンやダメージの効果が上昇し、必勝の抜き手を切る。", "クロエ（ウィンター）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 247, 129501, 129501, 129501, 0, 1, 2.09, 450, 0, 1, "2025/11/30 12:00:00", 1, 0, "ちえる", 129501, 0, "2025/12/15 14:59:59", 3, 1, 0, 0, "【物理】前衛で、ちぇるっとちぇるるな水着のちえるん。\nステータスアップで溜まる【ちぇる】を、自身の火力や\n支援能力に還元して、真冬の真夏をちぇらるれれぽぱぴ？", "チエル（ウィンター）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 550, 129601, 129601, 129601, 0, 0, 2.09, 450, 0, 1, "2026/10/23 12:00:00", 0, 0, "あねもね", 129601, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【物理】中衛で怜悧麗花の陣を張るアルラウネの妖魔人。\n敵の攻撃力、防御力、与ダメージを下げ、ＴＰを吸収し、\nＵＢの継続ダメージで領域を侵す敵を絶えず拒み退ける。", "アネモネ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 540, 129701, 129701, 129701, 0, 0, 2.09, 450, 0, 1, "2026/10/23 12:00:00", 0, 0, "ねふぃーねら", 129701, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【物理】中衛で万魔の頂点に君臨するジオ・ゲヘナの媛。\n環境効果【妨魔塵】で魔法攻撃を阻害し、行動速度アップ\n等の支援や苛烈な攻撃で無謀な不届き者を平伏させる。", "ネフィ＝ネラ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 269, 129801, 129801, 129801, 0, 5, 2.09, 450, 0, 1, "2026/03/31 12:00:00", 5, 0, "まこと", 129801, 0, "2026/04/15 11:59:59", 3, 1, 0, 0, "【物理】前衛で、情と熱意で仲間を束ねる指揮官の狼娘。\n敵の攻守を削りつつ、自分のＴＰ回復や対象が物防ダウン\n状態の時に発生する追撃で猛攻を仕掛け前線を突破する。", "マコト（コマンダー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 294, 129901, 129901, 129901, 0, 48, 1.84, 450, 0, 1, "2024/04/15 15:00:00", 6, 0, "えりこ", 129901, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】前衛で、苛烈な教えで味方を率いる狂恋の教官。\nＴＰ回復や防御支援に加え味方の人数で効果アップする攻\n撃支援と大ダメージで、味方全体を奮い立たせ敵を破る。", "エリコ（コマンダー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 150, 130001, 130001, 130001, 0, 0, 2.09, 450, 0, 1, "2026/11/16 12:00:00", 4, 0, "やまと", 130001, 0, "2026/11/30 11:59:59", 3, 1, 0, 0, "【物理】前衛で、豪胆にスリルを嗜む盗賊ギルドの長女。\n最前線で命を張りながら、獲得した【バンディダイス】の\n消費によって自らを大幅強化し、有象無象を地に伏せる。", "ヤマト");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 535, 130101, 130101, 130101, 0, 9, 2.09, 450, 0, 1, "2026/11/16 12:00:00", 7, 0, "わかな", 130101, 0, "2026/11/30 11:59:59", 3, 1, 0, 0, "【物理】中衛の、貧乏クジを引きがちな盗賊ギルド次女。\n召喚したスキッドがワカナをかばって前線に立ち、自身は\n攻撃支援にＨＰとＴＰ回復まで、献身的に味方を支える。", "ワカナ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 371, 130201, 130201, 130201, 0, 0, 1.84, 450, 0, 1, "2026/11/16 12:00:00", 5, 0, "ふぶき", 130201, 0, "2026/11/30 11:59:59", 3, 1, 0, 0, "【物理】中衛の、ナマイキで超天才な盗賊ギルドの三女。\n【味方バリアー♡】で自分へのダメージを味方に押し付け\nＨＰ最大でダメージアップする範囲攻撃で敵を蹂躙する。", "フブキ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 0, 130601, 0, 0, 0, 1, 0, 0, 0, 0, "2015/04/01 15:00:00", 4, 0, "れい", 130601, 0, "2030/12/31 15:00:00", 3, 1, 0, 0, "", "レイ（アストラル）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 563, 130701, 130701, 130701, 0, 7, 1.92, 450, 0, 2, "2026/05/22 12:00:00", 7, 0, "きょうか", 130701, 0, "2026/05/31 11:59:59", 3, 1, 0, 0, "【魔法】中衛で、お花畑に春を届ける花衣装の優等生。\nスキル発動回数に応じた効率的な自己強化やクリティカル\n時の追加効果を持つスキルとＵＢで勝利の風を吹かせる。", "キョウカ（スプリング）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 558, 130801, 130801, 130801, 0, 7, 1.84, 450, 0, 2, "2024/05/15 15:00:00", 7, 0, "すずめ", 130801, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】中衛で、春に彩られた花衣装のドジっ娘メイド。\n範囲内の敵にダメージを与えながら、多数の弱体化効果を\n持つスキルやＵＢを駆使して、穏やかに吹く勝利を掴む。", "スズメ（スプリング）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 440, 130901, 130901, 130901, 0, 7, 2.09, 450, 0, 2, "2024/06/15 15:00:00", 7, 0, "くるる", 130901, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】中衛で、皆を夢の世界に誘う宝石兎族の支配人。\nステータスアップ効果を受けるたびに【かばばん君】を増\nやし、反射的に味方へ攻撃支援の恩返しをしてしまう。", "クルル");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 702, 131001, 131001, 131001, 0, 7, 1.84, 450, 0, 2, "2026/06/22 12:00:00", 7, 0, "まほ", 131001, 0, "2026/06/30 11:59:59", 3, 1, 0, 0, "【魔法】後衛で、サーカスの舞台に輝くメルヘン少女。\n味方の攻防支援や敵の攻防弱体化の他【カーテンコール】\n付与時の追加ダメージスキルで、勝利のライトを照らす。", "マホ（ドリームパーク）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 165, 131101, 131101, 131101, 0, 52, 2.09, 450, 0, 1, "2024/06/30 12:00:00", 2, 0, "ねあ", 131101, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】前衛でハグの機会を窺う水着のスライムギャル。\n攻撃してきた敵に【ネバネバ】を自動で付着させ、攻撃力\nダウンやダメージ、束縛など複数の効果を引き起こす。", "ネア（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 753, 131201, 131201, 131201, 0, 54, 2.09, 450, 0, 2, "2026/07/15 12:00:00", 54, 0, "みそら", 131201, 0, "2026/07/31 11:59:59", 3, 1, 0, 0, "【魔法】後衛で夏の盛りにイイコトをする溌溂水着少女★\n【PSI★ストーム】をチャージし、連続攻撃で敵を殲滅し\nて、継続ＴＰ回復やバリアで抜け目なく味方を支援する。", "ミソラ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 0, 131301, 0, 0, 0, 1, 0, 0, 0, 0, "2015/04/01 15:00:00", 1, 0, "りり", 131301, 0, "2030/12/31 15:00:00", 3, 1, 1, 0, "", "リリ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 0, 131401, 0, 0, 0, 1, 0, 0, 0, 0, "2015/04/01 15:00:00", 1, 0, "くりあ", 131401, 0, "2030/12/31 15:00:00", 3, 1, 1, 0, "", "クリア");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 0, 131501, 0, 0, 0, 1, 0, 0, 0, 0, "2015/04/01 15:00:00", 1, 0, "ぷれしあ", 131501, 0, "2030/12/31 15:00:00", 3, 1, 1, 0, "", "プレシア");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 399, 131601, 131601, 131601, 0, 4, 1.92, 450, 0, 1, "2026/07/15 12:00:00", 4, 0, "りり", 131601, 0, "2026/07/31 11:59:59", 3, 1, 0, 0, "【物理】中衛で、夏の陽光のもと研鑽する妹系大和撫子。\n防御力アップに加えバリアやＨＰ回復で味方の守りを固め\nＴＰ回復や攻撃力ダウンをも巧みに操り、場を支配する。", "リリ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 743, 131701, 131701, 131701, 0, 53, 1.92, 450, 0, 2, "2026/08/26 12:00:00", 44, 0, "あめす", 131701, 0, "2026/08/31 11:59:59", 3, 1, 0, 0, "【魔法】後衛で、黄昏の水面に舞い降りる水着姿の妖精。\n行動速度アップやＴＰ支援をはじめとした多数のサポート\nを施しつつ、ＵＢの攻防弱体化で清爽に勝利へと導く。", "アメス（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 709, 131801, 131801, 131801, 0, 21, 2.09, 450, 0, 2, "2024/08/15 15:00:00", 7, 0, "ほまれ", 131801, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】後衛で夏の清涼に翼を休める水着姿の龍の首領。\n攻防弱体化に加え、ステータスダウン付与のたび増加する\n【日食】の数に応じたダメージで、抗う全てを灰に帰す。", "ホマレ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 725, 131901, 131901, 131901, 0, 23, 2.09, 450, 0, 2, "2024/08/31 12:00:00", 7, 1, "えみりあ", 131901, 0, "2030/12/31 15:00:00", 1, 1, 1, 0, "【魔法】後衛で、パックと共に戦う真夏のハーフエルフ。\n氷壁を生成するスキルや、強力なダメージと速度ダウンを\n付与するユニオンバーストで、敵の侵攻を食い止める。", "エミリア（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 775, 132001, 132001, 132001, 0, 21, 2.09, 450, 0, 2, "2025/10/10 12:00:00", 7, 1, "えきどな", 132001, 0, "2025/10/24 11:59:59", 3, 1, 0, 0, "【魔法】後衛で未知の世界との邂逅に胸躍る強欲の魔女。\n鮮烈な攻撃魔法をはじめ、味方への攻撃支援、敵の弱体化\nから自己蘇生まで、あらゆる魔法を振るい、欲を満たす。", "エキドナ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 146, 132101, 132101, 132101, 0, 24, 2.09, 450, 0, 1, "2025/10/10 12:00:00", 13, 1, "れむ", 132101, 0, "2025/10/24 11:59:59", 3, 1, 0, 0, "【物理】前衛で夏の日差しの中、余暇を楽しむ双子の妹。\nＵＢで鬼族の力を解放すると攻防両面に加えＨＰ吸収が\n上昇し、目に映る全てを【狂騒】のままに叩き伏せる。", "レム（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 721, 132201, 132201, 132201, 0, 7, 1.84, 450, 0, 2, "2026/10/15 12:00:00", 7, 0, "のぞみ", 132201, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【魔法】後衛で、希望を錬成するアルケミストアイドル。\n【錬金素材】から【パフューム】を創り、ダメージに加え\nＴＰ回復や攻撃支援能力を向上させて勝利の香りを運ぶ。", "ノゾミ（アルケミスト）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 754, 132301, 132301, 132301, 0, 7, 2.09, 450, 0, 2, "2026/05/11 12:00:00", 7, 0, "るいずまりー", 132301, 0, "2026/05/22 11:59:59", 3, 1, 0, 0, "【魔法】後衛で、底知れぬ叡智を秘めた天才錬金術師。\n高い方の防御力でダメージを受ける調和状態を付与し、\n２回まで性能が上昇していくＵＢで、妄想を爆発させる。", "ルイズマリー");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 501, 132401, 132401, 132401, 0, 0, 2.09, 450, 0, 1, "2025/06/20 12:00:00", 5, 0, "いろは", 132401, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】中衛で、大きな体で無邪気に遊び回る天才剣士。\n戦いの中で【剣圧】を溜め、その後のスキルやＵＢで物防\n一定無視のダメージを連発し、才気煥発の活躍を見せる。", "イロハ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 636, 132501, 132501, 132501, 0, 23, 2.09, 450, 0, 2, "2025/05/15 15:00:00", 7, 0, "その", 132501, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】後衛で、小柄で大人対応な錬金堂の省エネ店主。\n強力な弱体効果を与えながら、デバフ付与のたび増加する\n【虚脱】が80溜まると本気を出し定時厳守で戦い抜く。", "ソノ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 750, 132801, 132801, 132801, 0, 0, 2.09, 450, 0, 2, "2025/11/30 12:00:00", 7, 0, "らいらえる", 132801, 0, "2025/12/15 14:59:59", 3, 1, 0, 0, "【魔法】後衛で、雪白の肌を黒衣に包んだ甘美なる姫君。\n味方のＨＰを代償に強力なバリアを展開しつつ、バリアを\n起点とした高出力の二連撃で、聖夜の大樹に灯を点す。", "ライラエル（クリスマス）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 748, 132901, 132901, 132901, 0, 46, 2.09, 450, 0, 2, "2024/12/09 12:00:00", 5, 0, "いお", 132901, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】後衛で、心地良い眠りの中に訪れる聖夜の悪魔。\n最も魔法攻撃力が高い味方に【悪魔の口づけ】を付与し、\n攻撃支援とＴＰ回復による付きっきりの手ほどきをする。", "イオ（クリスマス）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 234, 133001, 133001, 133001, 0, 0, 2.09, 450, 0, 1, "2026/10/23 12:00:00", 0, 0, "ぐれいす", 133001, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【物理】前衛で、宙を舞うように戦う幽霊の守護騎士。\nＵＢで味方の攻撃と速度支援を行い、【レイスボディ】で\n敵の目を逃れ、不意を突く一撃で永遠の眠りにつかせる。", "グレイス");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 154, 133101, 133101, 133101, 0, 0, 1.75, 450, 0, 1, "2026/10/23 12:00:00", 0, 0, "うぁいおれっと", 133101, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【物理】前衛で、儚くも凛と咲くジオ・ニヴルヘルの姫。\n継続ダメージ効果を鈍化させる環境効果【忌火】で盾に、\n絶怠霊度の継続割合攻撃で矛となり、静寂の冥府を護る。", "ヴァイオレット");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 296, 133201, 133201, 133201, 0, 22, 2.09, 450, 0, 1, "2026/11/17 15:00:00", 4, 0, "もにか", 133201, 0, "2030/12/31 15:00:00", 1, 1, 0, 0, "【物理】前衛で、元日も元気にはしゃぎまわる軍人少女。\n与ダメージに応じて追加効果が強化されるＵＢと、発動ご\nとに成長する自己強化スキルで秩序を乱す者の目を回す。", "モニカ（ニューイヤー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 718, 133501, 133501, 133501, 0, 22, 2.09, 450, 0, 2, "2026/01/03 12:00:00", 4, 0, "されん", 133501, 0, "2026/01/15 11:59:59", 3, 1, 0, 0, "【魔法】後衛で、傍らで心を重ねる振袖姿の救護院の主。\n味方へのＴＰ回復の支援をしつつ、味方がＵＢを発動する\nたびダメージが上がるスキルで、共に困難を乗り越える。", "サレン（ニューイヤー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 445, 133601, 133601, 133601, 0, 0, 2.09, 450, 0, 1, "2026/01/03 12:00:00", 0, 0, "めどぅーさ", 133601, 0, "2026/01/15 11:59:59", 3, 1, 0, 0, "【物理】中衛で眷属と力を合わせて戦う誇り高き蛇乙女。\n【魔眼】の数に応じて効果量が上がるスキルのダメージと\n弱体化で範囲内の敵を追い詰め、鋭い瞳で石へと変える。", "メドゥーサ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 717, 133701, 133701, 133701, 0, 0, 2.09, 450, 0, 2, "2026/02/09 12:00:00", 8, 0, "らびりすた", 133701, 0, "2026/02/15 11:59:59", 3, 1, 0, 0, "【魔法】後衛で、始原の冠装を使いこなす『迷宮女王』。\n水属性の味方のＴＰ上昇を増加する領域を作り、連射攻撃\nで敵の防御を撃ち抜くことで七冠の力を敵に知らしめる。", "ラビリスタ（アルファ）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 759, 133801, 133801, 133801, 0, 0, 2.09, 450, 0, 2, "2026/02/09 12:00:00", 7, 0, "ねねか", 133801, 0, "2026/02/15 11:59:59", 3, 1, 0, 0, "【魔法】後衛から、始原の姿で戦況を操る『変貌大妃』。\n召喚したグレゴールから攻撃支援とＴＰ回復を受け、互い\nの魔力を合わせた連携攻撃で、幽玄なる玉座に君臨する。", "ネネカ（アルファ）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 228, 133901, 133901, 133901, 0, 0, 2.09, 450, 0, 1, "2026/02/09 12:00:00", 6, 0, "くりすてぃーな", 133901, 0, "2026/02/15 11:59:59", 3, 1, 0, 0, "【物理】前衛で、始原の冠装の力を振るう『誓約女君』。\n10行動目に攻撃力を大幅アップし、スキルに追撃を発生\nさせる【虚数】を得て隔絶した力で楯突く敵を抹消する。", "クリスティーナ（アルファ）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 746, 134001, 134001, 134001, 0, 0, 2.09, 450, 0, 2, "2026/10/23 12:00:00", 0, 0, "ふぃお", 134001, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【魔法】後衛で、アストルムの冒険へと導くガイド妖精。\nバフとバリアで味方を護りバリアを起点とする攻撃支援、\n風属性の味方への行動速度とＴＰの支援で仲間を支える。", "フィオ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 0, 134101, 0, 0, 0, 1, 0, 0, 0, 0, "2015/04/01 15:00:00", 5, 0, "ふぶき", 134101, 0, "2030/12/31 15:00:00", 3, 1, 0, 0, "", "フブキ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 0, 134201, 0, 0, 0, 1, 0, 0, 0, 0, "2015/04/01 15:00:00", 7, 0, "らいらえる", 134201, 0, "2030/12/31 15:00:00", 3, 1, 0, 0, "", "ライラエル（クリスマス）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 778, 134301, 134301, 134301, 0, 0, 2.09, 450, 0, 2, "2026/03/03 12:00:00", 7, 0, "らんふぁ", 134301, 0, "2026/03/16 9:59:59", 3, 1, 0, 0, "【魔法】後衛で儀装束を纏い精霊と心を通わせる唱喚士。\n敵の数に応じてダメージ量が変化する範囲攻撃や、魔法\n無効バリアなどの支援スキルで想いを詩に乗せ響かせる。", "ランファ（儀装束）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 773, 134401, 134401, 134401, 0, 21, 2.09, 450, 0, 2, "2025/03/15 15:00:00", 7, 0, "ちか", 134401, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】後衛で儀装束を纏い歌を紡ぎ伝えていく唱喚士。\n自分と最も近くの味方へ強力なバフとＴＰ回復を行うこと\nで攻撃を支援し、共に心を通わせ美しき旋律を奏でる。", "チカ（儀装束）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 719, 134501, 134501, 134501, 0, 0, 2.09, 450, 0, 2, "2026/04/15 12:00:00", 0, 0, "くろーちぇ", 134501, 0, "2026/04/30 11:59:59", 3, 1, 0, 0, "【魔法】後衛で超速飛行からの大火力を叩き込むロボ娘。\n上空から速度バフで味方全体を支援しつつ、自分のバリア\nを解除して力へと変え、世界の命運を背負い飛翔する！", "クローチェ（エアリアル）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 526, 134601, 134601, 134601, 0, 35, 2.09, 450, 0, 1, "2026/04/15 12:00:00", 35, 0, "あおい", 134601, 0, "2026/04/30 11:59:59", 3, 1, 0, 0, "【物理】中衛で巨大ロボを駆り戦うぼっちのパイロット。\n敵の弱体化や、味方へバリアを展開するスキルを持ち、\n鋼鉄の乙女から放つ光線はいかに堅固な守りも打ち破る。", "アオイ（パイロット）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 490, 134701, 134701, 134701, 0, 7, 2.09, 450, 0, 1, "2026/04/15 12:00:00", 7, 0, "ほうおう", 134701, 0, "2026/04/30 11:59:59", 3, 1, 0, 0, "【物理】中衛で、華麗に舞い踊る五色絢爛な煉華の鳳凰。\n攻撃力バフやバリア展開などの攻防支援と、多彩で豊富な\nＨＰ・ＴＰ供給を両立し、浄化の力で皆に安寧を授ける。", "ホウオウ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 485, 134801, 134801, 134801, 0, 1, 1.84, 450, 0, 1, "2026/06/10 12:00:00", 1, 0, "つむぎ", 134801, 0, "2026/06/22 11:59:59", 3, 1, 0, 0, "【物理】中衛から、新たな素材で紡ぐワイルドテーラー。\n最も物攻が高い他の味方へ重複速度アップやＴＰ・攻撃支\n援を仕立て、全体へのＨＰ回復と併せ攻守を両立させる。", "ツムギ（ジオ・ゲヘナ）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 196, 134901, 134901, 134901, 0, 0, 2.09, 450, 0, 1, "2026/06/10 12:00:00", 2, 0, "かのん", 134901, 0, "2026/06/22 11:59:59", 3, 1, 0, 0, "【物理】前衛で、おエレガントな高笑いを轟かすド令嬢。\nＵＢや敵からの攻撃で【お堪忍袋】が尽きると逆上し、強\n化されたスキルと行動パターンで華麗におリベンジする。", "カノン");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 785, 135001, 135001, 135001, 0, 21, 2.09, 450, 0, 2, "2026/07/03 12:00:00", 7, 0, "えりす", 135001, 0, "2026/07/15 11:59:59", 3, 1, 0, 0, "【魔法】後衛で、永く夢見た本物の夏に咲き綻ぶ黒薔薇。\n【いばらの冠】の呪縛は再臨により解き放たれ、調和状態\nや攻防支援、回復効果を施し、月下の浜辺に静かに佇む。", "エリス（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 143, 135101, 135101, 135101, 0, 4, 2.09, 450, 0, 1, "2026/07/03 12:00:00", 4, 0, "しぇふぃ", 135101, 0, "2026/07/15 11:59:59", 3, 1, 0, 0, "【物理】前衛で盛夏の白波を華麗に乗りこなす氷竜少女。\n敵全体を挑発し、被弾で溜まる【ぐずぐず】をＵＢで発散\nすることで周囲に攻撃支援と天真爛漫な笑顔を振りまく。", "シェフィ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 548, 135201, 135201, 135201, 0, 7, 2.09, 450, 0, 2, "2026/07/03 12:00:00", 7, 0, "ぷれしあ", 135201, 0, "2026/07/15 11:59:59", 3, 1, 0, 0, "【魔法】中衛で夏の食を満喫し、ぷかぷか漂う天然少女。\nＴＰ・攻撃支援やバリアは味方の数で効果量が変化し、物\n理と魔法攻撃力合算のダメージで夏の思い出を心に刻む。", "プレシア（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 413, 135301, 135301, 135301, 0, 54, 2.09, 450, 0, 1, "2026/07/31 12:00:00", 54, 0, "くりあ", 135301, 0, "2026/08/15 11:59:59", 3, 1, 0, 0, "【物理】中衛で友情の芽を育む、真夏の『普通』の少女。\n【プルメリアのお守り】で強力な一撃から先頭を守り、味\n方の数で効果量が変化するスキルを鮮やかに命中させる。", "クリア（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 553, 135401, 135401, 135401, 0, 52, 2.09, 450, 0, 2, "2026/07/31 12:00:00", 2, 0, "あねもね", 135401, 0, "2026/08/15 11:59:59", 3, 1, 0, 0, "【魔法】中衛で砂浜の木陰に微睡むアルラウネの妖魔人。\n行動速度アップや初回発動時に回復量が増加するＴＰ回復\nを起点に支援し、穏やかな木漏れ日と共にゆらゆら憩う。", "アネモネ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 213, 135501, 135501, 135501, 0, 0, 2.09, 450, 0, 1, "2026/10/23 12:00:00", 1, 0, "あいら", 135501, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【物理】前衛で、世界を守り笑顔を咲かせる情熱の豪炎。\n前方の敵全てを対象とする連撃の強化通常攻撃や、天楼覇\n断剣から放たれる極大ダメージの一閃で未来を切り拓く。", "アイラ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 198, 135601, 135601, 135601, 0, 0, 0.4, 450, 0, 1, "2026/10/23 12:00:00", 4, 0, "しなつ", 135601, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【物理】前衛から、風裂く刃で世界を護る孤高の剣豪。\n卓越した剣技で敵の攻撃を捌いて反撃し、初回ＵＢで生成\nする分身と共に疾風迅雷の攻めで、未来へと駆け抜ける。", "シナツ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 291, 135701, 135701, 135701, 0, 0, 1.84, 450, 0, 1, "2025/09/16 15:00:00", 1, 0, "ひより", 135701, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】前衛で、二人きりの月下の空旅にときめく黒猫。\n物防弱体の他、ダメージ100ヒット後には華麗なステップ\nの追撃とＴＰ回復量増加で、砂漠の夜空に花を咲かせる。", "ヒヨリ（サラサリア）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 830, 135801, 135801, 135801, 0, 0, 2.09, 450, 0, 2, "2026/09/30 12:00:00", 7, 0, "ゆきの", 135801, 0, "2026/10/15 11:59:59", 3, 1, 0, 0, "【魔法】後衛から、雪魄氷姿の三味を弾じる初心な雪女。\n多様なデバフ効果で敵を弱体化させ、最も魔防の低い敵の\n状態に応じて発生する追加効果で、冥府を真白に染める。", "ユキノ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 219, 135901, 135901, 135901, 0, 0, 1.84, 450, 0, 1, "2026/09/30 12:00:00", 3, 0, "さつき", 135901, 0, "2026/10/15 11:59:59", 3, 1, 0, 0, "【物理】前衛で、華奢な体躯に厚い仁義を宿す鬼のお嬢。\n攻防自己強化や行動不能無効化で豪胆に立ち続け、自分が\n呪詛状態の時に振るう追加攻撃で、怪力無双の力を示す。", "サツキ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 732, 136001, 136001, 136001, 0, 0, 2.09, 450, 0, 1, "2026/10/23 12:00:00", 11, 0, "あらくね", 136001, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【物理】後衛で、喪われた光を求めてもがく元『六凶』。\n敵のＵＢを遅延する【遮絶の操糸】や、味方単体のＵＢを\n連続発動可能にする【賦活の糸】を戦場に張り巡らせる。", "アラクネ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 432, 136101, 136101, 136101, 0, 0, 1.74, 450, 0, 1, "2025/10/24 12:00:00", 0, 1, "さくら", 136101, 0, "2025/11/03 11:59:59", 3, 1, 0, 0, "【物理】中衛で不運に抗い歌い続けるゾンビィアイドル。\n一度倒れても立ち上がり、ＴＰを糧に強化されるスキルの\nダメージと味方の支援で、サガの心をアストルムに刻む。", "サクラ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 198, 136201, 136201, 136201, 0, 3, 2.09, 450, 0, 1, "2025/11/14 15:00:00", 3, 0, "なーな", 136201, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】前衛でダメダメでも逃げず戦うアルミラージ娘。\n最も近くの味方に強化や行動不能無効の付与、回復を行い\n敵の注意をそらすことで、過酷な世界を生き延びる。", "ナーナ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 655, 136301, 136301, 136301, 0, 54, 2.09, 450, 0, 2, "2026/07/03 12:00:00", 35, 0, "みそら", 136301, 0, "2026/07/15 11:59:59", 3, 1, 0, 0, "【魔法】後衛で、シゲキ的な聖夜に鼓動高鳴る溌溂少女★\n【イルミネーションバレット】を消費して味方を支援し、\n40消費後は追加の範囲攻撃やバフでキュン★を届ける。", "ミソラ（クリスマス）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 382, 136401, 136401, 136401, 0, 21, 1.84, 450, 0, 2, "2026/07/03 12:00:00", 7, 0, "ゆい", 136401, 0, "2026/07/15 11:59:59", 3, 1, 0, 0, "【魔法】中衛で、騎士の隣に一歩踏み出す聖夜の魔法士。\n敵の注目を集めながら攻防支援を行い【聖夜の愛慕】が\n高まると、ＴＰ支援やダメージカットで優しく包み込む。", "ユイ（クリスマス）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 151, 136501, 136501, 136501, 0, 0, 2.09, 450, 0, 1, "2026/08/15 12:00:00", 5, 0, "しずる", 136501, 0, "2026/08/23 11:59:59", 3, 1, 0, 0, "【物理】前衛で、凛然と立ちはだかる新年のお姉ちゃん。\n挑発と行動不能無効で攻撃を鮮やかに捌き、状況に応じて\n物理・魔法を自在に操り、弟くんへの愛を見せつける。", "シズル（ニューイヤー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 0, 136601, 0, 0, 0, 1, 0, 0, 0, 0, "2015/04/01 15:00:00", 1, 0, "めどぅーさ", 136601, 0, "2030/12/31 15:00:00", 1, 0, 0, 0, "", "メドゥーサ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 0, 136701, 0, 0, 0, 1, 0, 0, 0, 0, "2015/04/01 15:00:00", 8, 0, "らびりすた", 136701, 0, "2030/12/31 15:00:00", 3, 1, 0, 0, "", "ラビリスタ（アルファ）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 0, 136801, 0, 0, 0, 1, 0, 0, 0, 0, "2015/04/01 15:00:00", 7, 0, "らんふぁ", 136801, 0, "2030/12/31 15:00:00", 3, 1, 0, 0, "", "ランファ（儀装束）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 409, 136901, 136901, 136901, 0, 0, 2.09, 450, 0, 1, "2026/05/22 12:00:00", 3, 0, "るるぃ", 136901, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】中衛でうねる、珍味な触手の小姓見習いタコ娘。\nＴＰ回復、継続ＨＰ回復、バリアで味方をもてなし、多様\nな弱体効果を与える自慢の墨で、敵を真っ黒に染める。", "ルルィ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 566, 137101, 137101, 137101, 0, 47, 2.09, 450, 0, 2, "2025/08/15 15:00:00", 8, 0, "にのん", 137101, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】中衛で陽光の下、煌く水面を共に駆けるシノビ。\n【水遁の印】を自らの攻撃力へと変え、束縛フィールドと\n水遁の術で最も遠い敵とその周囲に速やかな天誅を下す。", "ニノン（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 0, 137201, 0, 0, 0, 2, 0, 0, 0, 0, "2015/04/01 15:00:00", 2, 0, "らびりすた", 137201, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "", "ラビリスタ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 0, 137301, 0, 0, 0, 1, 0, 0, 0, 0, "2015/04/01 15:00:00", 2, 0, "かのん", 137301, 0, "2030/12/31 15:00:00", 3, 1, 0, 0, "", "カノン");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 688, 137401, 137401, 137401, 0, 21, 2.09, 450, 0, 2, "2026/10/31 12:00:00", 7, 0, "かすみ", 137401, 0, "2026/11/16 11:59:59", 3, 1, 0, 0, "【魔法】後衛で、聖なる光に包まれ微笑み祈るシスター。\n攻防デバフを操り【真実の導き】が集まると最大３キャラ\nへの攻撃が最も魔防の低い敵を追及し、真理を照らす。", "カスミ（シスター）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 0, 137501, 0, 0, 0, 1, 0, 0, 0, 0, "2015/04/01 15:00:00", 1, 0, "あいら", 137501, 0, "2030/12/31 15:00:00", 3, 1, 0, 0, "", "アイラ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 733, 137601, 137601, 137601, 0, 0, 2.09, 450, 0, 2, "2026/10/23 12:00:00", 7, 0, "こっころ", 137601, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【魔法】後衛で、主さまを想い“進化”した嚮導の巫女。\n極大ダメージのＵＢで敵を穿ち、【進化超越】の権能によ\nって、味方のバフやダメージを、限界を超え成長させる。", "コッコロ（嚮導幼君）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 0, 137801, 0, 0, 0, 1, 0, 0, 0, 0, "2015/04/01 15:00:00", 7, 0, "ゆきの", 137801, 0, "2030/12/31 15:00:00", 3, 1, 0, 0, "", "ユキノ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 684, 137901, 137901, 137901, 0, 8, 2.09, 450, 0, 2, "2026/08/15 12:00:00", 8, 0, "りの", 137901, 0, "2026/08/23 11:59:59", 3, 1, 0, 0, "【魔法】後衛で絵馬に込めた想いを胸に抱く晴れ着の妹。\nクリティカル時に威力が上がる矢で敵を撃ち抜き、味方\n全体への攻撃支援や継続ＴＰ回復で厄を払い福を届ける。", "リノ（ニューイヤー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 154, 138001, 138001, 138001, 0, 0, 2.09, 450, 0, 1, "2026/09/10 12:00:00", 0, 0, "うぁいおれっと", 138001, 0, "2026/09/22 11:59:59", 3, 1, 0, 0, "【物理】前衛から慈愛の心で冥府を包む彼岸の屍姫。\nＵＢは敵全体を呑み込む割合ダメージを与え、【冥海の加\n護】を消費して味方の攻防ダウン効果までも禊ぎ清める。", "ヴァイオレット（イサナミ）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 729, 138101, 138101, 138101, 0, 0, 2.09, 450, 0, 2, "2026/09/10 12:00:00", 0, 0, "らいらえる", 138101, 0, "2026/09/22 11:59:59", 3, 1, 0, 0, "【魔法】後衛で、民とハーモニーを奏でる天使の姫君。\nステータスアップ効果を受け【エクスマキナ】が溜まると\n行動パターンが変化し、絶え間ない弓撃で神威を示す。", "ライラエル（パルフェクト）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 502, 138201, 138201, 138201, 0, 0, 2.09, 450, 0, 1, "2026/09/10 12:00:00", 0, 0, "ねふぃーねら", 138201, 0, "2026/09/22 11:59:59", 3, 1, 0, 0, "【物理】中衛から怯懦を退け、万魔を率する煉獄の鉄媛。\n千変万化の躰は行動速度アップを始めとする多彩な支援と\nすべての敵の弱体を両立し、天地万象を掌の内に収める。", "ネフィ＝ネラ（鬼面仏心）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 142, 138301, 138301, 138301, 0, 0, 2.09, 450, 0, 1, "2026/10/23 12:00:00", 0, 0, "ぺこりーぬ", 138301, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【物理】前衛で女神の血脈と矜持を揮う全力全開の王女。\n物理攻撃力の高い味方を【裁定の盾】で庇い、自身は圧倒\n的な防御とＨＰ回復で前線に立ち幸せな食卓を守り抜く。", "ペコリーヌ（アストライア）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 0, 138601, 0, 0, 0, 1, 0, 0, 0, 0, "2015/04/01 15:00:00", 1, 0, "さくら", 138601, 0, "2030/12/31 15:00:00", 3, 1, 0, 0, "", "サクラ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 539, 138701, 138701, 138701, 0, 55, 2.09, 450, 0, 1, "2026/09/30 12:00:00", 7, 0, "わかな", 138701, 0, "2026/10/15 11:59:59", 3, 1, 0, 0, "【物理】中衛で恥じらいながらも激戦に飛び込む桃闘者。\n味方を【スパイクシール】で守りつつ、自身は物理防御力\nダウンで敵を切り崩し、鍛え上げた桃尻を存分に振るう。", "ワカナ（ウィンター）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 571, 138801, 138801, 138801, 0, 8, 2.09, 450, 0, 1, "2026/09/30 12:00:00", 8, 0, "しおり", 138801, 0, "2026/10/15 11:59:59", 3, 1, 0, 0, "【物理】中衛で、過酷なお尻の世界を生き抜く桃闘者。\n攻防ダウンを併せ持つＵＢを矢継ぎ早に放ち、ステータス\nダウン効果で付与する【魅惑の矢】で敵を骨抜きにする。", "シオリ（ウィンター）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 429, 138901, 138901, 138901, 0, 0, 2.09, 450, 0, 1, "2026/10/31 12:00:00", 4, 0, "ぐれいす", 138901, 0, "2026/11/16 11:59:59", 3, 1, 0, 0, "【物理】中衛で、妖しく跳ねるバニーの幽霊守護騎士。\n物理攻撃力を代償に物理クリダメを極大アップし、【ブラ\nックうさ耳】で油断した敵の虚を突き、御首を頂戴する。", "グレイス（バニー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 816, 139001, 139001, 139001, 0, 7, 2.09, 450, 0, 2, "2026/10/31 12:00:00", 7, 0, "きょうか", 139001, 0, "2026/11/16 11:59:59", 3, 1, 0, 0, "【魔法】後衛で、破滅の運命にあらがうお嬢様？優等生。\n【呪いの鎖】の溢れる魔力で魔防デバフやＴＰ、速度支援\nを行うが、限界を迎えると永久的狂気に陥ってしまう。", "キョウカ（ゴシック）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 770, 139101, 139101, 139101, 0, 0, 2.09, 450, 0, 2, "2026/10/23 12:00:00", 0, 0, "きゃる", 139101, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【魔法】後衛で、天の星を瞳に映し、仲間と進む黒猫娘。\n敵全体を激烈に弱体化させながら、【千里真眼】状態時に\n未来を視通す能力で仲間をあらゆる脅威から遠ざける。", "キャル（覇瞳天星）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 486, 139201, 139201, 139201, 0, 0, 2.09, 450, 0, 2, "2026/04/30 12:00:00", 0, 1, "みほ", 139201, 0, "2030/12/31 15:00:00", 1, 1, 1, 0, "【魔法】中衛で臨機応変に作戦を指揮する戦車道の乙女。\n召喚したボコが敵の攻撃を引き付けている間に、周囲の\n味方の攻撃、回復支援によって、全員での勝利を目指す。", "ミホ（ガルパン）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 700, 139301, 139301, 139301, 0, 0, 2.09, 450, 0, 1, "2026/04/30 12:00:00", 0, 1, "まほ", 139301, 0, "2026/05/22 11:59:59", 3, 1, 0, 0, "【物理】後衛から必中の一射で敵を貫く西住流の継承者。\n【榴弾】を装填した状態のＵＢは、防御力を無視する火傷\nフィールドを発生させ、圧倒的な戦力差で敵を蹂躙する。", "マホ（ガルパン）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 322, 139401, 139401, 139401, 0, 0, 1.04, 450, 0, 1, "2026/05/11 12:00:00", 0, 1, "えりか", 139401, 0, "2026/05/22 11:59:59", 3, 1, 0, 0, "【物理】中衛から迅速な強襲で戦局を切り拓く双剣使い。\nバトル開始直後からＴＰを消費する強力なスキルの連撃で\n敵の防御力を一気に下げ、敵陣深くまで浸透突破する。", "エリカ（ガルパン）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 453, 139501, 139501, 139501, 0, 0, 2.09, 450, 0, 2, "2026/05/31 12:00:00", 0, 0, "りり", 139501, 0, "2026/06/10 11:59:59", 3, 1, 0, 0, "【魔法】中衛で、寄る辺無き魂を繋ぎ導く清廉の戦乙女。\nダメージと共に敵の魔防を削ぎ、継続ダメージを与える聖\n浄の光が戦乙女の聖槍を降り注がせ、敵を清め祓う。", "リリ（ヴァルキュリア）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 150, 139601, 139601, 139601, 0, 0, 2.09, 450, 0, 2, "2026/06/22 12:00:00", 2, 0, "くりあ", 139601, 0, "2026/06/30 11:59:59", 3, 1, 0, 0, "【魔法】前衛で、奇跡により魂の疵を癒す浄罪の戦乙女。\n味方を物理攻撃から堅牢に守り、継続ダメージを与える聖\n浄の光を敵に浴びせ、戦乙女の聖槍による天罰を下す。", "クリア（ヴァルキュリア）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 500, 139701, 139701, 139701, 0, 0, 2.09, 450, 0, 2, "2026/06/10 12:00:00", 0, 0, "ぷれしあ", 139701, 0, "2026/06/22 11:59:59", 3, 1, 0, 0, "【魔法】中衛で、正義の光で邪な魂を祓う勧善の戦乙女。\n多彩な支援効果で味方を支え、継続ダメージを与える聖浄\nの光が戦乙女の聖槍を喚び寄せ、悪をこらしめる。", "プレシア（ヴァルキュリア）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 386, 139801, 139801, 139801, 0, 0, 2.09, 450, 0, 1, "2026/10/23 12:00:00", 0, 0, "しぇふぃ", 139801, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【物理】中衛で兄妹の絆と不撓の心で覚醒した氷竜少女。\n個も群も薙ぎ払うＵＢと、【氷竜超克】状態時に発生する\n追撃状態で敵を咬断し、大切な人と歩む未来を切り拓く。", "シェフィ（ヴァードラッヘ）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 757, 139901, 139901, 139901, 0, 55, 2.09, 450, 0, 2, "2026/07/03 12:00:00", 55, 0, "るいずまりー", 139901, 0, "2026/07/15 11:59:59", 3, 1, 0, 0, "【魔法】後衛で、大人の階段を上りたい水着の錬金術師。\n発動回数で性能が上昇するＵＢとスキルで、調和状態の\n付与と攻防たゆまぬ支援を行い、ひと夏の思い出を創る。", "ルイズマリー（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 730, 140001, 140001, 140001, 0, 54, 2.09, 450, 0, 2, "2026/07/15 12:00:00", 54, 0, "くれじった", 140001, 0, "2026/07/31 11:59:59", 3, 1, 0, 0, "【魔法】後衛で、リゾート建設に奔走する水着の女商人。\n初回発動時に強力な攻撃支援と一定時間魔攻・物防・魔防\nダウンを無効化するスキルで、豪奢に味方を駆り立てる。", "クレジッタ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 376, 140101, 140101, 140101, 0, 54, 2.09, 450, 0, 1, "2026/07/31 12:00:00", 54, 0, "ふぶき", 140101, 0, "2026/08/15 11:59:59", 3, 1, 0, 0, "【物理】中衛であざとくラヴを奪う超天才びしょーじょ。\n毒と火傷で弱らせた敵をあざ笑うかのように、自分と\n先頭の味方へＴＰ回復や行動不能無効を付与し強化する。", "フブキ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 582, 140201, 140201, 140201, 0, 43, 2.09, 450, 0, 2, "2026/08/15 12:00:00", 43, 0, "うぁんぴぃ", 140201, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【魔法】中衛でけんぞくとラヴを集めるつよつよ吸血姫。\nスキルでＴＰを吸収し、【チャームスローブ】を消費して\n放つＵＢは、ほとばしるカワいさで敵を骨抜きにする。", "ヴァンピィ（サマー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 744, 140301, 140301, 140301, 0, 0, 2.09, 450, 0, 2, "2026/10/23 12:00:00", 0, 0, "てぃあ", 140301, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【魔法】後衛から、中立で平等とうそぶく認識の修正者。\n敵の認識を乱して弱体効果を付与し、一方で味方が受ける\n混乱、誘惑状態を無効化しお気に入りの彼に肩入れする。", "ティア");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 780, 140401, 140401, 140401, 0, 0, 2.09, 450, 0, 1, "2026/09/10 12:00:00", 0, 0, "りーざ", 140401, 0, "2026/09/22 11:59:59", 3, 1, 0, 0, "【物理】後衛で、答えを求め彷徨うダークエルフの咎人。\nＵＢで放つ矢の呪いは二度重なれば呪詛、三度重なれば\n強烈な割合ダメージとなり、立ちはだかる敵を殺める。", "リーザ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 396, 140501, 140501, 140501, 0, 0, 2.09, 450, 0, 1, "2026/08/31 12:00:00", 0, 0, "うるむ", 140501, 0, "2026/09/10 11:59:59", 3, 1, 0, 0, "【物理】中衛で、愛する者たちのため本意気を放つ妹竜。\n【決意の流星】を溜め覚醒すると、攻撃スキルが再発動し\nさらに味方の火力を引き上げ、渦炎で敵を灰燼に変える。", "ヴルム（ヴァルムドラッヘ）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 400, 140601, 140601, 140601, 0, 0, 2.09, 450, 0, 1, "2026/09/22 12:00:00", 0, 0, "くろーちぇ", 140601, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】中衛から必殺クローで敵全体を圧潰するロボ娘。\n自分へのバフと敵へのデバフで【水陸可変ブースター】が\n起動し、高頻度のＵＢでダメージの大渦潮を巻き起こす！", "クローチェ（サブマリン）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 431, 140701, 140701, 140701, 0, 0, 2.09, 450, 0, 1, "2026/09/30 12:00:00", 0, 0, "されん", 140701, 0, "2026/10/09 11:59:59", 3, 1, 0, 0, "【物理】中衛で、敵影に照準を定める戦場のサレンママ。\n７種以上の弱体効果があれば更に効果が増すスキルで敵の\n装甲に風穴を開け、臨機応変の戦術で窮地を逆手に取る。", "サレン（ガンナー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 512, 140801, 140801, 140801, 0, 0, 2.09, 450, 0, 2, "2026/10/09 12:00:00", 0, 0, "あめす", 140801, 0, "2026/10/23 11:59:59", 3, 1, 0, 0, "【魔法】中衛で、まばゆい弾丸の雨を降らす銃装の妖精。\n一定回数ダメージを与えるたび割合ダメージを発生させ、\n【ペタロ】で敵からの攻撃をひらりと躱し、無効化する。", "アメス（ガンナー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 780, 140901, 140901, 140901, 0, 0, 2.09, 450, 0, 2, "2026/10/23 12:00:00", 0, 0, "あぐらいあ", 140901, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【魔法】後衛で働いて働いて働く仕事中毒な光の大精霊。\n自分に展開されているバリアに応じて性能が強化される\nスキルを武器に、ブラックな環境さえ輝く笑顔で照らす。", "アグライア");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 368, 141001, 141001, 141001, 0, 0, 2.09, 450, 0, 1, "2026/10/31 12:00:00", 0, 1, "ごーるどしっぷ", 141001, 0, "2030/12/31 15:00:00", 1, 1, 1, 0, "【物理】中衛から破天荒に翻弄するゴルシちゃんだぜ☆\n後ろでコソコソしてる敵を狙い打ち！　ラストスパートの\n追込でダメージレースをぶっちぎってやんよオラァッ！", "ゴールドシップ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 261, 141101, 141101, 141101, 0, 0, 2.09, 450, 0, 1, "2026/10/31 12:00:00", 0, 1, "あーもんどあい", 141101, 0, "2026/11/30 11:59:59", 3, 1, 0, 0, "【物理】前衛でLoAを駆ける超×９負けず嫌いなウマ娘。\n自分より攻撃力の高い味方がいると、【スタミナ】を消費\nしてスキルの性能を強化し、さらなる高みへと躍進する。", "アーモンドアイ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 737, 141201, 141201, 141201, 0, 0, 2.09, 450, 0, 2, "2026/11/10 12:00:00", 0, 1, "らっきーらいらっく", 141201, 0, "2026/11/30 11:59:59", 3, 1, 0, 0, "【魔法】後衛で気高く咲き誇る時を待つ、忍耐のウマ娘。\nバトル後半になると内に秘めた【スタミナ】を解き放ち、\nしとやかな足取りで立ち塞がる敵を一息にかわす。", "ラッキーライラック");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 398, 141301, 141301, 141301, 0, 0, 2.09, 450, 0, 1, "2026/11/16 12:00:00", 0, 1, "でありんぐたくと", 141301, 0, "2026/11/30 11:59:59", 3, 1, 0, 0, "【物理】中衛でファンタジーの大自然を満喫するウマ娘。\n物理・魔法を問わず自身の糧とし、温存した【スタミナ】\nをふりしぼる差し脚は、巨大な熊といえど震え上がる。", "デアリングタクト");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 0, 141401, 0, 0, 0, 1, 0, 0, 0, 0, "2015/04/01 15:00:00", 1, 0, "しずる", 141401, 0, "2030/12/31 15:00:00", 1, 0, 0, 0, "", "シズル（ニューイヤー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 0, 141501, 0, 0, 0, 1, 0, 0, 0, 0, "2015/04/01 15:00:00", 0, 0, "うぁいおれっと", 141501, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "", "ヴァイオレット（イサナミ）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 0, 141601, 0, 0, 0, 1, 0, 0, 0, 0, "2015/04/01 15:00:00", 4, 0, "ぐれいす", 141601, 0, "2030/12/31 15:00:00", 3, 1, 0, 0, "", "グレイス（バニー）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 0, 143001, 0, 0, 0, 1, 0, 0, 0, 0, "2015/04/01 15:00:00", 0, 0, "るいずまりー", 143001, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "", "ルイズマリー");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 245, 170101, 105701, 170101, 0, 34, 1.965, 450, 4, 1, "2015/04/01 15:00:00", 34, 0, "じーた", 170101, 0, "2030/12/31 15:00:00", 3, 0, 0, 0, "【物理】前衛で、先手必勝の大技を繰り出す騎空士。\nスキルによるＴＰ回復は、ユニオンバーストの発動を早め\nバトルの序盤から敵前衛に大ダメージを与える。", "ジータ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 199, 180101, 180101, 180101, 0, 0, 1.62, 450, 7, 1, "2026/10/23 12:00:00", 0, 0, "ひより", 180101, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【物理】前衛で炎翼を背に敵を粉砕する、陽気な元気娘。\n戦いが続く程に自身の攻撃能力を強めるスキルを操り、\n高めた力で放つ超爆の一撃は、あらゆる敵を塵と化す。", "ヒヨリ（プリンセス）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 767, 180201, 180201, 180201, 0, 0, 1.92, 450, 1, 2, "2026/10/23 12:00:00", 0, 0, "ゆい", 180201, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【魔法】後衛から極大魔法で敵を滅する願いの魔法士。\nＴＰを回復しつつ攻撃力を累積アップする補助スキルで\n自身の力を高め、強力な範囲攻撃を放ち敵を一掃する。", "ユイ（プリンセス）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 377, 180301, 180301, 180301, 0, 0, 1.965, 450, 7, 1, "2026/10/23 12:00:00", 0, 0, "れい", 180301, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【物理】中衛で風刃を従え激戦を流麗に征く嵐翼の剣士。\n敵が多い程に効果が高まる自己強化スキルで、自身を奮い\n立たせ、強力な範囲攻撃スキルで一切の敵を鏖滅する。", "レイ（プリンセス）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 155, 180401, 180401, 180401, 0, 0, 1.965, 450, 1, 1, "2026/10/23 12:00:00", 0, 0, "ぺこりーぬ", 180401, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【物理】前衛で、攻防共に絶大な力を誇る腹ペコ王女。\nＨＰが多い時は爆発的な攻撃力で、いかなる敵をも屠り、\nＨＰが減ると自己回復能力を得て、鉄壁の護りを見せる。", "ペコリーヌ（プリンセス）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 555, 180501, 180501, 180501, 0, 0, 2.14, 450, 1, 1, "2026/10/23 12:00:00", 0, 0, "こっころ", 180501, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【物理】中衛で、絶大な補助スキルを繰出す純白の巫女。\n味方の攻撃力とクリティカルダメージを強化しつつ、\n二つの全体回復スキルで味方を堅固に守護し勝利へ導く。", "コッコロ（プリンセス）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 747, 180601, 180601, 180601, 0, 0, 1.92, 450, 1, 2, "2026/10/23 12:00:00", 0, 0, "きゃる", 180601, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【魔法】後衛で、極大魔法を操り敵を討つ姫装の猫娘。\n回復や補助を兼ねた各攻撃スキルを駆使し戦況を整え、\n極大威力のユニオンバーストを撃ち込み敵を燼滅する。", "キャル（プリンセス）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 732, 180701, 180701, 180701, 0, 0, 1.75, 450, 1, 1, "2026/10/23 12:00:00", 0, 0, "はつねしおり", 180701, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【物理】後衛から、真の絆の力を発揮する仲良し姉妹。\n敵の数が増えるほど威力が高まる攻撃スキルと、周りの\n味方を強化するスキルを操り、立ち塞がる敵を一掃する。", "ハツネ＆シオリ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 465, 180801, 180801, 180801, 0, 0, 1.5, 450, 1, 1, "2026/10/23 12:00:00", 0, 0, "みそぎみみきょうか", 180801, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【物理】中衛で敵単体に必殺の一撃を放つ仲良しトリオ。\n３人の力を合わせて放つ攻撃は、相手の弱点に合わせて\n物理から魔法攻撃に変化し、どんな強い敵も退治する！", "ミソギ＆ミミ＆キョウカ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 421, 180901, 180901, 180901, 0, 0, 2.09, 450, 1, 1, "2026/10/23 12:00:00", 0, 0, "あきのされん", 180901, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【物理】中衛で背を預けあう最高の好敵手で親友の二人。\n味方の物理攻撃をサポートしつつＨＰとＴＰを継続回復し\nＨＰが多いほど威力が増すＵＢで、共に勝利の道を征く。", "アキノ＆サレン");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 577, 181001, 181001, 181001, 0, 0, 2.09, 450, 1, 2, "2026/10/23 12:00:00", 0, 0, "あんぐれあ", 181001, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【魔法】中衛で、魔力共鳴し連撃を放つマナリアの双姫。\nステータスアップ効果を受けると増加する【友情の魔印】\nがスキルを強化し、波長を合わせた炎の魔槍で敵を討つ。", "アン＆グレア");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 551, 181101, 181101, 181101, 0, 0, 1.92, 450, 1, 1, "2026/10/23 12:00:00", 0, 0, "しずるりの", 181101, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【物理】中衛でお揃い衣装の、真偽を超えた仲良し姉妹。\n攻守共に味方を支えるシズルと、クリティカル時に強力な\nダメージを与えるリノ、姉妹の絆で困難を跳ね除ける！", "シズル＆リノ");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 368, 181201, 181201, 181201, 0, 0, 1.92, 450, 1, 1, "2026/10/23 12:00:00", 0, 0, "しぇふぃ", 181201, 0, "2026/10/31 11:59:59", 3, 1, 0, 0, "【物理】中衛で新たな力と共に再廻する姫装の氷竜少女。\n環境効果【絶氷】でクリティカルダメージを高め、火力と\n手数を併せ持つ剣技で、再び共に歩むため道を切り開く。", "シェフィ（プリンセス）");
INSERT INTO `v1_bbc4b012ab5d83ce83b76cd2a1474b8fe57a28552ca1150e7e07bb3d975edf46` VALUES (0, 0, 0, 190801, 0, 0, 0, 1, 0, 0, 0, 1, "2015/04/01 15:00:00", 1, 0, "かりん", 190801, 0, "2030/12/31 15:00:00", 1, 0, 0, 0, "", "カリン");
